// SPDX-License-Identifier: GPL-2.0
pragma solidity ^0.8.24;

import {ERC20Upgradeable} from "@openzeppelin/contracts-upgradeable/token/ERC20/ERC20Upgradeable.sol";
import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";

import {AccessControl} from "../access/AccessControl.sol";
import {IVault} from "./interfaces/IVault.sol";
import {IManager} from "./interfaces/IManager.sol";
import {Roles} from "../libraries/Roles.sol";
import {Errors} from "../libraries/Errors.sol";
import {AddressLib} from "../libraries/AddressLib.sol";
import {MathLib} from "../libraries/MathLib.sol";

/**
 * @title Vault
 * @author YieldFi Team
 * @notice ERC20Upgradeable token contract representing vault shares
 * @dev ERC20 token with custom name/symbol functionality and share locking
 * @dev Features:
 *      - Custom name and symbol support (overrides ERC20 metadata)
 *      - Share locking: Tracks locked shares per user (for redemption queue)
 *      - Manager integration: References Manager contract for NAV and Registry access
 *      - Pure token contract: NAV logic moved to separate NAV contract
 */
contract Vault is ERC20Upgradeable, AccessControl, IVault {
    using AddressLib for address;
    using MathLib for uint256;
    using SafeERC20 for IERC20;

    // ═══════════════════════════════════════════════════════════════════
    //                          STATE VARIABLES
    // ════════════════════════════════════════════════════════ ═══════════

    /// @notice Custom name storage (overrides ERC20 name)
    string private _customName;

    /// @notice Custom symbol storage (overrides ERC20 symbol)
    string private _customSymbol;

    /// @notice Locked shares per user (for redemption queue, etc.)
    /// @dev key: user (address), value: lockedShares (uint256)
    mapping(address user => uint256 lockedShares) public lockedShares;

    /// @notice Manager contract address (for accessing NAV and Registry)
    address public manager;

    /// @notice Registry contract address (for accessing Registry)
    address public ccipAdmin;

    /**
     * @dev Storage gap for upgradeable contracts
     * CRITICAL: Update gap when adding/removing state variables
     * Current usage:
     * - _customName: 1 slot (string, if <= 31 bytes) or more
     * - _customSymbol: 1 slot (string, if <= 31 bytes) or more
     * - lockedShares: 1 slot (mapping)
     * - manager: 1 slot
     * - AccessControl parent: 1 slot (administrator address)
     * - ERC20Upgradeable parent: 5 slots (_name, _symbol, _balances mapping, _totalSupply, _allowances mapping)
     * Total: 10 slots used (assuming short strings)
     * Gap: 72 - 10 = 62 slots remaining
     * Note: _gap follows OpenZeppelin's standard pattern for upgradeable contracts
     */
    uint256[62] private _gap;

    // ═══════════════════════════════════════════════════════════════════
    //                             EVENTS
    // ═══════════════════════════════════════════════════════════════════

    // Events are defined in IVault interface

    // ═══════════════════════════════════════════════════════════════════
    //                         INITIALIZATION
    // ═══════════════════════════════════════════════════════════════════

    /// @custom:oz-upgrades-unsafe-allow constructor
    constructor() {
        _disableInitializers();
    }

    /**
     * @notice Initialize the vault token
     * @param name_ Token name
     * @param symbol_ Token symbol
     * @param administrator_ Administrator contract address
     * @param manager_ Manager contract address
     */
    function initialize(
        string memory name_,
        string memory symbol_,
        address administrator_,
        address manager_
    ) external initializer {
        administrator_.requireNonZeroContract();
        manager_.requireNonZeroContract();

        // Initialize parent contracts
        __ERC20_init(name_, symbol_);
        __AccessControl_init(administrator_);

        // Initialize custom name and symbol storage
        _customName = name_;
        _customSymbol = symbol_;
        manager = manager_;
    }

    // ═══════════════════════════════════════════════════════════════════
    //                      EXTERNAL VIEW FUNCTIONS
    // ═══════════════════════════════════════════════════════════════════

    /**
     * @notice Returns the name of the token
     * @return The name of the token
     */
    function name() public view override returns (string memory) {
        return _customName;
    }

    /**
     * @notice Returns the symbol of the token
     * @return The symbol of the token
     */
    function symbol() public view override returns (string memory) {
        return _customSymbol;
    }

    /**
     * @notice Returns the decimals of the token
     * @dev Tokens always have 18 decimals
     * @return Always returns 18
     */
    function decimals() public pure override returns (uint8) {
        return 18; // all the tokens are of 18 decimals
    }

    /**
     * @notice Get the base asset address for this vault
     * @return asset Base asset address
     * @dev Returns the base asset via Manager pass-through function
     */
    function asset() external view override returns (address) {
        return IManager(manager).getVaultAsset(address(this));
    }

    /**
     * @notice Convert shares to assets using current NAV
     * @param shares Amount of shares to convert (18 decimals)
     * @return assets Amount of assets (in base asset decimals)
     * @dev Uses Manager pass-through function to calculate asset value
     */
    function convertToAssets(
        uint256 shares
    ) external view override returns (uint256 assets) {
        return
            IManager(manager).convertVaultSharesToAssets(address(this), shares, true);
    }

    /**
     * @notice Get total assets managed by this vault (ERC4626-compatible)
     * @return Total assets in base asset (in base asset decimals)
     * @dev Returns the total assets via Manager pass-through function
     */
    function totalAssets() external view override returns (uint256) {
        return IManager(manager).totalAssets(address(this));
    }

    function _reduceFees(uint256 amount, bool isRedemption) internal view returns (uint256 netAmount) {
        address _asset = IManager(manager).getVaultAsset(address(this));
        (netAmount,) = IManager(manager).calculateFees(address(this), _asset, amount, isRedemption);
    }

    /**
     * @notice Preview deposit - calculate shares for given assets
     * @param assets Amount of assets to deposit (in base asset decimals)
     * @return shares Amount of shares to receive (18 decimals)
     * @dev ERC4626-compatible preview function
     */
    function previewDeposit(
        uint256 assets
    ) external view override returns (uint256 shares) {
        uint256 _shares = IManager(manager).convertVaultAssetsToShares(address(this), assets, false);
        return _reduceFees(_shares, false);
    }

    /**
     * @notice Preview redeem - calculate assets for given shares
     * @param shares Amount of shares to redeem (18 decimals)
     * @return assets Amount of assets to receive (in base asset decimals)
     * @dev ERC4626-compatible preview function
     */
    function previewRedeem(
        uint256 shares
    ) external view override returns (uint256 assets) {
        uint256 _assets = IManager(manager).convertVaultSharesToAssets(address(this), shares, true);
        return _reduceFees(_assets, true);
    }

    /**
     * @notice Preview withdrawal - calculate shares needed to withdraw given assets
     * @param assets Amount of assets to withdraw (in base asset decimals)
     * @return shares Amount of shares needed (18 decimals)
     * @dev ERC4626-compatible preview function
     * @dev Inverse of previewRedeem: calculates shares needed for assets
     */
    function previewWithdraw(
        uint256 assets
    ) external view override returns (uint256 shares) {
        uint256 _shares = IManager(manager).convertVaultAssetsToShares(address(this), assets, true);
        return _reduceFees(_shares, true);
    }

    /**
     * @notice Preview mint - calculate assets required to mint shares
     * @param shares Amount of shares to mint (18 decimals)
     * @return assets Amount of assets required (in base asset decimals)
     * @dev ERC4626-compatible preview function
     */
    function previewMint(
        uint256 shares
    ) external view override returns (uint256 assets) {
        uint256 _assets = IManager(manager).convertVaultSharesToAssets(address(this), shares, false);
        return _reduceFees(_assets, false);
    }

    /**
     * @notice Convert assets to shares using current NAV
     * @param assets Amount of assets to convert (in base asset decimals)
     * @return shares Amount of shares (18 decimals)
     * @dev ERC4626-compatible conversion function
     */
    function convertToShares(
        uint256 assets
    ) external view override returns (uint256 shares) {
        return
            IManager(manager).convertVaultAssetsToShares(address(this), assets, true);
    }

    /**
     * @notice Maximum amount of assets that can be deposited (ERC4626-compatible)
     * @return maxAssets Maximum amount of assets that can be deposited
     * @dev Returns type(uint256).max unless limited by vault configuration
     */
    function maxDeposit(
        address /* receiver */
    ) external pure override returns (uint256 maxAssets) {
        // Note: Vault limits checking will be implemented when LIMITS feature is enabled
        // For now, return max deposit amount
        return type(uint256).max;
    }

    /**
     * @notice Maximum amount of shares that can be redeemed (ERC4626-compatible)
     * @param owner Address that owns the shares
     * @return maxShares Maximum amount of shares that can be redeemed
     * @dev Returns owner's balance (unlocked shares)
     */
    function maxRedeem(
        address owner
    ) external view override returns (uint256 maxShares) {
        return balanceOf(owner);
    }

    /**
     * @notice Approve manager to spend base asset with infinite allowance
     * @dev This function should be called once after vault initialization to set infinite allowance
     * @dev Can be called multiple times safely (will only set if not already set)
     */
    function approveManager() external onlyOperator {
        address baseAsset = IManager(manager).getVaultAsset(address(this));
        IERC20(baseAsset).approve(manager, type(uint256).max);
    }

    /**
     * @notice Deposit assets into vault and receive shares (ERC4626-compatible)
     * @param assets Amount of assets to deposit (in base asset decimals)
     * @param receiver Address to receive shares
     * @return shares Amount of shares minted (18 decimals)
     * @dev Pass-through to Manager.deposit using vault's base asset
     * @dev Requires approveManager() to be called first to set infinite allowance
     */
    function deposit(
        uint256 assets,
        address receiver
    ) external returns (uint256 shares) {
        IManager managerContract = IManager(manager);
        address baseAsset = managerContract.getVaultAsset(address(this));

        // Transfer assets to the vault from the sender
        IERC20(baseAsset).safeTransferFrom(msg.sender, address(this), assets);

        // receiver blacklisting is chcecked in the manager contract hence only msg.sender is checked
        if (isBlacklisted(msg.sender)) {
            revert Errors.AddressBlacklisted(msg.sender);
        }

        managerContract.validateGreenlist(address(this), msg.sender, receiver);

        // Calculate minimum shares expected (use 0 for no slippage protection in ERC4626 interface)
        // Since this is for base asset, we don't need to worry about slippage protection
        // No oracles are called in this case.
        uint256 minShares = 0;

        // Deposit assets into the vault (manager already has infinite allowance)
        return
            managerContract.deposit(
                address(this),
                baseAsset,
                assets,
                receiver,
                minShares,
                bytes32(0)
            );
    }

    /**
     * @notice Get CCIP admin address
     * @return admin CCIP admin address
     * @dev Returns the administrator contract address (CCIP admin can be managed through Administrator)
     */
    function getCCIPAdmin() external view returns (address) {
        return ccipAdmin;
    }

    /**
     * @notice Latest Round data from price oracle
     * @return roundId Round ID
     * @return answer Answer
     * @return startedAt Started at
     * @return updatedAt Updated at
     * @return answeredInRound Answered in round
     */
    function latestRoundData()
        external
        view
        returns (
            uint80 roundId,
            int256 answer,
            uint256 startedAt,
            uint256 updatedAt,
            uint80 answeredInRound
        )
    {
        uint256 nav = IManager(manager).getNAV(address(this));
        if (nav == 0) {
            return (0, 0, 0, 0, 0);
        }
        startedAt = block.timestamp;
        roundId = uint80(block.number);

        // Casting to int256 is safe because NAV is always positive and within int256 range
        // forge-lint: disable-next-line(unsafe-typecast)
        return (roundId, int256(nav), startedAt, startedAt, roundId);
    }

    /**
     * @notice getRate for price informaton
     * @return rate Rate for price information
     * @dev Returns the rate for price information in 18 decimals
     */
    function getRate() external view returns (uint256 rate) {
        return IManager(manager).getNAV(address(this));
    }

    // ═══════════════════════════════════════════════════════════════════
    //                      EXTERNAL WRITE FUNCTIONS
    // ═══════════════════════════════════════════════════════════════════

    /**
     * @notice Mint tokens (only callable by authorized contracts)
     * @dev Allows Manager or Bridge contracts to mint tokens
     * @param to Address to receive tokens
     * @param amount Amount of tokens to mint
     */
    function mint(address to, uint256 amount) external {
        _checkTokenOperatorRole(msg.sender);
        to.requireNonZero();
        if (amount == 0) revert Errors.ZeroAmount();
        _mint(to, amount);
    }

    /**
     * @notice Burn tokens (only callable by Token Operator)
     * @dev Allows contracts with TOKEN_OPERATOR_ROLE to burn tokens
     * @param from Address to burn tokens from
     * @param amount Amount of tokens to burn
     */
    function burn(address from, uint256 amount) external {
        _checkTokenOperatorRole(msg.sender);
        from.requireNonZero();
        if (amount == 0) revert Errors.ZeroAmount();
        _burn(from, amount);
    }

    /**
     * @notice Spender allowance for a user
     * @param owner Owner address
     * @param spender Spender address
     * @param amount Amount of allowance to spend
     */
    function spendAllowance(
        address owner,
        address spender,
        uint256 amount
    ) external override {
        if (msg.sender != manager) revert Errors.UnauthorizedCaller();
        _spendAllowance(owner, spender, amount);
    }

    /**
     * @notice Spend allowance for a validation
     * @param owner Owner address
     * @param spender Spender address
     * @param amount Amount of allowance to spend
     * @dev Additional check to prevent spending allowance from blacklisted addresses
     */
    function _spendAllowance(
        address owner,
        address spender,
        uint256 amount
    ) internal override {
        _notBlacklisted(spender);
        super._spendAllowance(owner, spender, amount);
    }

    /**
     * @notice Set token name and symbol
     * @param newName New token name
     * @param newSymbol New token symbol
     */
    function setNameAndSymbol(
        string calldata newName,
        string calldata newSymbol
    ) external onlyOperator {
        if (bytes(newName).length == 0) revert Errors.ZeroAmount();
        if (bytes(newSymbol).length == 0) revert Errors.ZeroAmount();

        string memory oldName = _customName;
        string memory oldSymbol = _customSymbol;

        _customName = newName;
        _customSymbol = newSymbol;

        emit NameAndSymbolUpdated(
            address(this),
            oldName,
            oldSymbol,
            newName,
            newSymbol
        );
    }

    /**
     * @notice Lock shares for a user (only callable by Token Operator)
     * @dev Locks shares to prevent transfer. Used for redemption queues, etc.
     * @param user Address to lock shares for
     * @param amount Amount of shares to lock
     */
    function lockShares(address user, uint256 amount) external {
        _checkTokenOperatorRole(msg.sender);
        user.requireNonZero();
        if (amount == 0) revert Errors.ZeroAmount();

        // Check user has sufficient unlocked balance
        uint256 unlockedBalance = balanceOf(user);
        if (unlockedBalance < amount) {
            revert Errors.InsufficientShares(unlockedBalance, amount);
        }

        lockedShares[user] = MathLib.safeAdd(lockedShares[user], amount);
        emit SharesLocked(address(this), user, amount);
    }

    /**
     * @notice Unlock shares for a user (only callable by Token Operator)
     * @dev Unlocks previously locked shares, allowing transfer
     * @param user Address to unlock shares for
     * @param amount Amount of shares to unlock
     */
    function unlockShares(address user, uint256 amount) external {
        _checkTokenOperatorRole(msg.sender);
        user.requireNonZero();
        if (amount == 0) revert Errors.ZeroAmount();

        // Check user has sufficient locked shares
        if (lockedShares[user] < amount) {
            revert Errors.InsufficientShares(lockedShares[user], amount);
        }

        lockedShares[user] = MathLib.safeSub(lockedShares[user], amount);
        emit SharesUnlocked(address(this), user, amount);
    }

    // ═══════════════════════════════════════════════════════════════════
    //                      INTERNAL VIEW FUNCTIONS
    // ═══════════════════════════════════════════════════════════════════

    /**
     * @notice Check if caller has TOKEN_OPERATOR_ROLE
     * @dev Reverts if caller does not have TOKEN_OPERATOR_ROLE
     * @param caller Address to check role for
     */
    function _checkTokenOperatorRole(address caller) internal view {
        if (!_hasRole(Roles.TOKEN_OPERATOR_ROLE, caller)) {
            revert Errors.Unauthorized(caller, Roles.TOKEN_OPERATOR_ROLE);
        }
    }

    // ═══════════════════════════════════════════════════════════════════
    //                      INTERNAL WRITE FUNCTIONS
    // ═══════════════════════════════════════════════════════════════════

    /**
     * @notice Update balances during transfer/mint/burn
     * @dev Override to prevent transferring locked shares and block transfers during pause
     * @dev Includes blacklist checks for from and to addresses
     * @param from Address to transfer from (address(0) for mint)
     * @param to Address to transfer to (address(0) for burn)
     * @param amount Amount of tokens to transfer
     */
    function _update(
        address from,
        address to,
        uint256 amount
    ) internal override {
        // Check if vault is paused (read through manager)
        if (IManager(manager).isVaultPaused(address(this))) {
            revert Errors.VaultPaused(address(this));
        }

        // Blacklist checks: prevent blacklisted addresses from sending or receiving tokens
        if (from != address(0)) {
            _notBlacklisted(from);
        }
        if (to != address(0)) {
            _notBlacklisted(to);
        }

        if (from != address(0)) {
            // For burns (to == address(0)), always unlock the shares first
            // For transfers/mints, check unlocked balance only
            uint256 availableBalance = balanceOf(from); // Unlocked balance for transfers
            if (availableBalance < amount) {
                revert Errors.InsufficientShares(availableBalance, amount);
            }
        }
        // Call parent _update which handles the actual balance updates
        super._update(from, to, amount);
    }

    /**
     * @notice Get balance of account excluding locked shares
     * @dev Override to exclude locked shares from user balance for consistency
     * @param account Address to check balance for
     * @return balance Active (unlocked) balance of the account
     */
    function balanceOf(
        address account
    ) public view override(ERC20Upgradeable, IERC20) returns (uint256 balance) {
        uint256 totalBalance = super.balanceOf(account);
        uint256 locked = lockedShares[account];
        // Return active balance (total - locked)
        // Safe subtraction: locked can never exceed totalBalance due to _update protection
        balance = MathLib.safeSub(totalBalance, locked);
    }

    /**
     * @notice Set CCIP admin address
     * @param ccipAdmin_ New CCIP admin address
     */
    function setCCIPAdmin(address ccipAdmin_) external onlyEmergencyOperator {
        ccipAdmin_.requireNonZeroContract();
        ccipAdmin = ccipAdmin_;
    }
}

