import {IAccessControl} from "../../interfaces/IAccessControl.sol";
import {IEvents} from "./IEvents.sol";

/**
 * @title IManager
 * @author YieldFi Team
 * @notice Interface for Manager contract that handles multi-asset deposits, yield distribution, and asset whitelisting
 */
interface IManager is IAccessControl, IEvents {

    // ═══════════════════════════════════════════════════════════════════
    //                        VAULT MANAGEMENT
    // ═══════════════════════════════════════════════════════════════════

    /**
     * @notice Check if an address is a registered vault
     * @param vault Address to check
     * @return isRegistered True if vault is registered
     */
    function isVault(address vault) external view returns (bool isRegistered);

    // ═══════════════════════════════════════════════════════════════════
    //                        ASSET WHITELISTING
    // ═══════════════════════════════════════════════════════════════════

    /**
     * @notice Whitelist or blacklist an asset for a vault
     * @param vault Vault address
     * @param asset Asset address
     * @param status True to whitelist, false to blacklist
     */
    function setAssetWhitelist(
        address vault,
        address asset,
        bool status
    ) external;

    /**
     * @notice Disable asset whitelist for a vault
     * @param vault Vault address
     * @param asset Asset address
     */
    function disableAsset(address vault, address asset) external;

    // ═══════════════════════════════════════════════════════════════════
    //                        REDEMPTION CONTROL
    // ═══════════════════════════════════════════════════════════════════

    // ═══════════════════════════════════════════════════════════════════
    //                        MULTI-ASSET DEPOSITS
    // ═══════════════════════════════════════════════════════════════════

    /**
     * @notice Deposit assets into a vault (supports multi-asset deposits)
     * @param vault Vault address
     * @param asset Asset address (can be different from vault base asset)
     * @param amount Amount of assets to deposit
     * @param receiver Address to receive shares
     * @param minShares Minimum shares to receive (slippage protection)
     * @param referralCode Optional referral partner code (keccak hash, bytes32)
     * @return shares Amount of shares minted
     */
    function deposit(
        address vault,
        address asset,
        uint256 amount,
        address receiver,
        uint256 minShares,
        bytes32 referralCode
    ) external returns (uint256 shares);

    // ═══════════════════════════════════════════════════════════════════
    //                      REDEMPTION QUEUE MANAGEMENT
    // ═══════════════════════════════════════════════════════════════════

    /**
     * @notice Request redemption by locking shares and adding to queue
     * @param vault Vault address
     * @param shares Amount of shares to redeem
     * @param owner Owner of the shares (must have sufficient balance, or caller must have allowance)
     * @param receiver Address to receive the redemption assets
     * @dev If owner != msg.sender, caller must have allowance to spend owner's shares
     */
    function requestRedemption(
        address vault,
        uint256 shares,
        address owner,
        address receiver,
        bytes32 referralCode
    ) external;

    /**
     * @notice Cancel a redemption request
     * @param vault Vault address
     * @param queueIndex Index of redemption request to cancel
     * @dev Caller must be the owner or have allowance to cancel on behalf of owner
     */
    function cancelRedemption(address vault, uint256 queueIndex) external;

    /**
     * @notice Process redemption from queue (only curator)
     * @param vault Vault address
     * @param queueIndex Index of redemption request to process
     * @param gasFeeShares Gas fees in shares to deduct from redemption
     */
    function processRedemption(address vault, uint256 queueIndex, uint256 gasFeeShares) external;

    /**
     * @notice Update NAV and mint management/performance fees (only operator)
     * @param vault Vault address
     * @param newNav New NAV value (18 decimals)
     * @param vestingEndTime Vesting end timestamp
     * @param managementFee Management fee amount in shares (18 decimals)
     * @param performanceFee Performance fee amount in shares (18 decimals)
     */
    function updateNav(
        address vault,
        uint256 newNav,
        uint256 vestingEndTime,
        uint256 managementFee,
        uint256 performanceFee
    ) external;

    /**
     * @notice Get the base asset address for a vault
     * @param vault Vault address
     * @return asset Base asset address
     */
    function getVaultAsset(address vault) external view returns (address asset);

    /**
     * @notice Convert shares to assets for a vault using current NAV
     * @param vault Vault address
     * @param shares Amount of shares to convert (18 decimals)
     * @param isRedemption True if redemption, false if deposit
     * @return assets Amount of assets (in base asset decimals)
     */
    function convertVaultSharesToAssets(
        address vault,
        uint256 shares,
        bool isRedemption
    ) external view returns (uint256 assets);

    /**
     * @notice Convert assets to shares for a vault using current NAV
     * @param vault Vault address
     * @param assets Amount of assets to convert (in base asset decimals)
     * @param isRedemption True if redemption, false if deposit
     * @return shares Amount of shares (18 decimals)
     */
    function convertVaultAssetsToShares(
        address vault,
        uint256 assets,
        bool isRedemption
    ) external view returns (uint256 shares);

    /**
     * @notice Get total assets managed by a vault (ERC4626-compatible)
     * @param vault Vault address
     * @return Total assets in base asset (in base asset decimals)
     * @dev Calculates total assets as: NAV × totalSupply / PRECISION
     */
    function totalAssets(address vault) external view returns (uint256);

    /**
     * @notice Check if a vault is paused (checks both vault-level and global pause)
     * @param vault Vault address
     * @return paused True if vault is paused or global pause is active
     */
    function isVaultPaused(address vault) external view returns (bool paused);

    /**
     * @notice Get NAV for a vault
     * @param vault Vault address
     * @return NAV NAV value (18 decimals)
     */
    function getNAV(address vault) external view returns (uint256 NAV);

    /**
    * @notice Validate greeen list addresses for a vault
    * @param vault Vault address
    * @param caller Caller address
    * @param receiver Receiver address
     */
    function validateGreenlist(address vault, address caller, address receiver) external view;

    /**
     * @notice Calculate fees for a vault
     * @param vault Vault address
     * @param asset Asset address
     * @param amount Amount of assets
     * @param isRedemption True if redemption, false if deposit
     * @return netAmount Net amount after fees ( in the @param amount terms)
     * @return feeAmount Fee amount ( in the @param amount terms)
     */
    function calculateFees(address vault, address asset, uint256 amount, bool isRedemption) external view returns (uint256 netAmount, uint256 feeAmount);

    // ═══════════════════════════════════════════════════════════════════
    //                      EMERGENCY FUNCTIONS
    // ═══════════════════════════════════════════════════════════════════

}

