    // ═══════════════════════════════════════════════════════════════════
    //                        COMMON ERRORS
    // ═══════════════════════════════════════════════════════════════════

    /// @notice Thrown when an amount is zero
    error ZeroAmount();

    /// @notice Thrown when an address is zero
    error ZeroAddress();

    /// @notice Thrown when an address does not contain contract code
    error NotContract(address account);

    /// @notice Thrown when NAV is zero
    error ZeroNAV();

    /// @notice Thrown when arithmetic operation overflows
    error ArithmeticOverflow();

    /// @notice Thrown when arithmetic operation underflows
    error ArithmeticUnderflow();

    /// @notice Thrown when division by zero occurs
    error DivisionByZero();

    /// @notice Thrown when safe cast operation underflows
    error SafeCastUnderflow();

    /// @notice Thrown when two addresses are the same
    error SameAddress();

    /// @notice Thrown when an array length is invalid
    error InvalidArrayLength();

    /// @notice Thrown when a signature is invalid
    error InvalidSignature();

    /// @notice Thrown when a time is invalid
    error InvalidTime(uint256 time);

    // ═══════════════════════════════════════════════════════════════════
    //                        VAULT ERRORS
    // ═══════════════════════════════════════════════════════════════════

    /// @notice Thrown when insufficient shares are available
    error InsufficientShares(uint256 available, uint256 required);

    /// @notice Thrown when insufficient balance is available
    error InsufficientBalance(uint256 available, uint256 required);

    /// @notice Thrown when a transfer fails
    error TransferFailed();

    /// @notice Thrown when deviation exceeds maximum allowed for an operation
    /// @param operationType Type of operation (bytes32 identifier, e.g., "PRICE_DEVIATION", "NAV_CHANGE", "FEE_AMOUNT")
    /// @param deviation Actual deviation value (18 decimals for percentages)
    /// @param maxAllowed Maximum allowed deviation (18 decimals for percentages)
    error ExcessiveDeviation(bytes32 operationType, uint256 deviation, uint256 maxAllowed);

    /// @notice Thrown when queue index is invalid
    error InvalidQueueIndex(uint256 queueIndex);

    /// @notice Thrown when user is not on greenlist
    error NotOnGreenlist(address user);

    /// @notice Thrown when user deposit exceeds limit
    error ExceedsUserDepositLimit(uint256 amount, uint256 limit);

    /// @notice Thrown when total deposit exceeds limit
    error ExceedsTotalDepositLimit(uint256 amount, uint256 limit);

    /// @notice Thrown when deposit is below minimum
    error BelowMinimumDeposit(uint256 amount, uint256 minimum);

    /// @notice Thrown when user mismatch occurs
    error MismatchedUser(address user, address requestUser);

    // ═══════════════════════════════════════════════════════════════════
    //                        MANAGER ERRORS
    // ═══════════════════════════════════════════════════════════════════

    /// @notice Thrown when vault is not registered
    error VaultNotRegistered(address vault);

    /// @notice Thrown when asset is not whitelisted
    error AssetNotWhitelisted(address vault, address asset);

    /// @notice Thrown when redemptions are disabled for a vault
    error RedemptionsDisabledForVault(address vault);

