    error NavAlreadyInitialized(address vault);

    /// @notice Thrown when signer does not have operator role
    error SignerNotOperator(address signer);

    /// @notice Thrown when data has already been processed
    error DuplicateData(bytes32 dataHash);

    // ═══════════════════════════════════════════════════════════════════
    //                        ORACLE ERRORS
    // ═══════════════════════════════════════════════════════════════════

    /// @notice Thrown when oracle caller is unauthorized
    error UnauthorizedOracle();

    /// @notice Thrown when timestamp is invalid
    error InvalidTimestamp(uint256 timestamp);

    /// @notice Thrown when data is stale
    error StaleData(uint256 age);

    /// @notice Thrown when price is invalid
    error InvalidPrice(uint256 price);

    /// @notice Thrown when price is stale
    error StalePrice(address asset, uint256 age);

    /// @notice Thrown when sequencer is down (L2 chains)
    error SequencerDown();

    // ═══════════════════════════════════════════════════════════════════
    //                        FEATURE ERRORS
    // ═══════════════════════════════════════════════════════════════════

    /// @notice Thrown when feature is not registered
    error FeatureNotRegistered(bytes32 featureId);

    /// @notice Thrown when feature is already registered
    error FeatureAlreadyRegistered(bytes32 featureId);

    /// @notice Thrown when feature is already enabled
    error FeatureAlreadyEnabled(address vault, bytes32 featureId);

    /// @notice Thrown when feature is not enabled
    error FeatureNotEnabled(address vault, bytes32 featureId);

    /// @notice Thrown when feature contract is invalid
