pragma solidity ^0.8.24;

/**
 * @title IEvents
 * @author YieldFi Team
 * @notice Centralized event definitions for YieldFi v3 protocol
 * @dev All core contracts should inherit from this interface for consistent event definitions
 */
interface IEvents {
    // ═══════════════════════════════════════════════════════════════════
    //                            ENUMS
    // ═══════════════════════════════════════════════════════════════════

    /// @notice Fee type enum for FeeTransferred event
    enum FeeType {
        DepositFee,
        RedemptionFee,
        ManagementFee,
        PerformanceFee
    }

    // ═══════════════════════════════════════════════════════════════════
    //                        MANAGER EVENTS
    // ═══════════════════════════════════════════════════════════════════

    /// @notice Emitted when an asset is whitelisted/blacklisted for a vault
    event AssetWhitelisted(
        address indexed vault,
        address indexed asset,
        bool status
    );

    /// @notice Emitted when assets are deposited into a vault
    event Deposit(
        address indexed vault,
        address indexed asset,
        address indexed sender,
        address receiver,
        uint256 assets,
        uint256 shares,
        uint256 feeShares,
        bytes32 referralCode
    );

    /// @notice Emitted when a redemption is requested
    event RedemptionRequested(
        address indexed vault,
        address indexed user,
        uint256 indexed queueIndex,
        uint256 shares,
        address receiver,
        bytes32 referralCode
    );

    /// @notice Emitted when a redemption is cancelled
    event RedemptionCancelled(
        address indexed vault,
        address indexed user,
        uint256 indexed queueIndex,
        uint256 shares,
        address receiver
    );

    /// @notice Emitted when a redemption is processed
    event RedemptionProcessed(
        address indexed vault,
        address indexed user,
        address indexed receiver,
        uint256 queueIndex,
        uint256 assets,
        uint256 effectiveNav,
        uint256 burnShares,
        uint256 gasFeeShares
    );

    /// @notice Emitted when NAV is updated and fees are minted
    event NAVUpdated(
        address indexed vault,
        uint256 indexed newNav,
        uint256 vestingEndTime,
        uint256 managementFee,
        uint256 performanceFee
    );

    /// @notice Emitted when maximum NAV change percentage guardrail is updated
    event MaxNavChangePercentUpdated(address indexed vault, uint256 maxNavChangePercent);

    // ═══════════════════════════════════════════════════════════════════
    //                        REGISTRY EVENTS
    // ═══════════════════════════════════════════════════════════════════

    /// @notice Emitted when a vault is registered
    event VaultRegistered(
        address indexed vault,
        address indexed depositRecipient,
        address indexed redemptionSource,
        address feeReceiver,
        address curator,
        address baseAsset,
        uint256 managementFee,
        uint256 performanceFee
    );

    /// @notice Emitted when curator is updated
    event CuratorUpdated(
        address indexed vault,
        address indexed oldCurator,
        address indexed newCurator
    );

    /// @notice Emitted when a vault is unregistered
    event VaultUnregistered(address indexed vault);

    /// @notice Emitted when deposit recipient is updated
    event DepositRecipientUpdated(
        address indexed vault,
        address indexed oldDepositRecipient,
        address indexed newDepositRecipient
    );

    /// @notice Emitted when deposit recipient change is pending (two-step transfer)
    event DepositRecipientPending(
        address indexed vault,
        address indexed pendingDepositRecipient
    );

    /// @notice Emitted when redemption source is updated
    event RedemptionSourceUpdated(
        address indexed vault,
        address indexed oldRedemptionSource,
        address indexed newRedemptionSource
    );

    /// @notice Emitted when fee receiver is updated
    event FeeReceiverUpdated(
        address indexed vault,
        address indexed oldFeeReceiver,
        address indexed newFeeReceiver
    );

    /// @notice Emitted when fee receiver change is pending (two-step transfer)
    event FeeReceiverPending(
        address indexed vault,
        address indexed pendingFeeReceiver
    );

    /// @notice Emitted when vault fees are configured
    event VaultFeesConfigured(
        address indexed vault,
        uint256 managementFee,
        uint256 performanceFee
    );

    /// @notice Emitted when redemption is enabled/disabled for a vault
    event RedemptionEnabled(address indexed vault, bool enabled);

    /// @notice Emitted when base asset is updated for a vault
    event BaseAssetUpdated(
        address indexed vault,
        address indexed oldBaseAsset,
        address indexed newBaseAsset
    );

    /// @notice Emitted when a vault is paused
    event VaultPaused(address indexed vault, address indexed curator);

    /// @notice Emitted when a vault is unpaused
    event VaultUnpaused(address indexed vault, address indexed operator);


    /// @notice Emitted when fee buffers are set for a vault
    event FeeBuffersSet(address indexed vault, uint256 managementFeeBuffer, uint256 performanceFeeBuffer);

    // ═══════════════════════════════════════════════════════════════════
    //                        VAULT EVENTS
    // ═══════════════════════════════════════════════════════════════════

    /// @notice Emitted when vault token name and symbol are updated
    event NameAndSymbolUpdated(
        address indexed vault,
        string oldName,
        string oldSymbol,
        string newName,
        string newSymbol
    );

    /// @notice Emitted when shares are locked for a user
    event SharesLocked(address indexed vault, address indexed user, uint256 amount);

    /// @notice Emitted when shares are unlocked for a user
    event SharesUnlocked(address indexed vault, address indexed user, uint256 amount);

    // ═══════════════════════════════════════════════════════════════════
    //                        FEE STORE EVENTS
    // ═══════════════════════════════════════════════════════════════════

    /// @notice Emitted when transaction fee shares are stored (deposit + redemption fees)
    event TransactionFeeStored(
        address indexed vault,
        uint256 shares,
        uint256 totalStored
    );

    /// @notice Emitted when fees are transferred directly to feeReceiver
    /// @param vault Vault address
    /// @param feeReceiver Address receiving the fees
    /// @param feeShares Amount of fee shares transferred
    /// @param feeType Type of fee: DepositFee, RedemptionFee, ManagementFee, PerformanceFee
    /// @param asset For deposits: the asset being deposited. For redemptions: the base asset of the vault
    event FeeTransferred(
        address indexed vault,
        address indexed feeReceiver,
        uint256 feeShares,
        FeeType feeType,
        address asset
    );

    /// @notice Emitted when transaction fees are withdrawn
    event TransactionFeesWithdrawn(
        address indexed vault,
        address indexed recipient,
        uint256 transactionFeeShares
    );

    /// @notice Emitted when asset fee configuration is updated
    event AssetFeeConfigUpdated(
        address indexed vault,
        address indexed asset,
        uint256 depositFee,
        uint256 redemptionFee
    );

    /// @notice Emitted when treasury is updated
    event TreasuryUpdated(address indexed treasury);

    /// @notice Emitted when treasury change is pending (two-step transfer)
    event TreasuryPending(address indexed pendingTreasury);

    /// @notice Emitted when contracts are set
    event ContractsSet(
        address indexed registry,
        address indexed featureRegistry,
        address indexed navContract,
        address priceOracle
    );

    /// @notice Emitted when price oracle is set
    event PriceOracleSet(address indexed priceOracle);

    /// @notice Emitted when fees are clawed back to treasury
    event FeesClawedBack(
        address indexed vault,
        uint8 indexed feeType,
        address indexed treasury,
        uint256 shares
    );

    // ═══════════════════════════════════════════════════════════════════
    //                        FEATURE EVENTS
    // ═══════════════════════════════════════════════════════════════════

    /// @notice Emitted when feature is initialized
    event FeatureInitialized(address indexed vault, bytes32 indexed featureId);

    /// @notice Emitted when feature is enabled
    event FeatureEnabled(address indexed vault, bytes32 indexed featureId);

    /// @notice Emitted when feature is disabled
    event FeatureDisabled(address indexed vault, bytes32 indexed featureId);
}

