    event OperationExecuted(bytes32 indexed operationId, address indexed executor);

    /// @notice Emitted when an operation is cancelled
    event OperationCancelled(bytes32 indexed operationId, address indexed canceller);

    /// @notice Emitted when timelock delay is updated
    event TimelockDelayUpdated(uint256 oldDelay, uint256 newDelay);

    // ═══════════════════════════════════════════════════════════════════
    //                         VIEW FUNCTIONS
    // ═══════════════════════════════════════════════════════════════════

    /**
     * @notice Get the current timelock delay
     * @return delay The timelock delay in seconds
     */
    function getTimelockDelay() external view returns (uint256 delay);

    /**
     * @notice Check if an operation is scheduled
     * @param operationId The operation identifier
     * @return scheduled True if the operation is scheduled
     */
    function isOperationScheduled(bytes32 operationId) external view returns (bool scheduled);

    /**
     * @notice Check if an operation is ready for execution
     * @param operationId The operation identifier
     * @return ready True if the operation is ready
     */
    function isOperationReady(bytes32 operationId) external view returns (bool ready);

    /**
     * @notice Get operation details
     * @param operationId The operation identifier
     * @return target The target contract address
     * @return data The calldata for the operation
     * @return readyTime The timestamp when operation becomes ready
     * @return expiryTime The timestamp when operation expires
     */
    function getOperation(
        bytes32 operationId
    )
        external
        view
        returns (
            address target,
            bytes memory data,
            uint256 readyTime,
            uint256 expiryTime
        );

    // ═══════════════════════════════════════════════════════════════════
    //                        ADMIN FUNCTIONS
    // ═══════════════════════════════════════════════════════════════════

    /**
     * @notice Schedule an operation for delayed execution
     * @param target The target contract address
     * @param data The calldata for the operation
     * @return operationId The unique identifier for the operation
     */
    function scheduleOperation(
        address target,
        bytes calldata data
    ) external returns (bytes32 operationId);

    /**
     * @notice Execute a scheduled operation
     * @param operationId The operation identifier
     */
    function executeOperation(bytes32 operationId) external;

    /**
     * @notice Cancel a scheduled operation
     * @param operationId The operation identifier
     */
    function cancelOperation(bytes32 operationId) external;

    /**
     * @notice Update the timelock delay
     * @param newDelay The new delay in seconds
     */
    function updateTimelockDelay(uint256 newDelay) external;
}

