/**
 * @title Manager
 * @author YieldFi Team
 * @notice Central hub for managing YieldFi vaults, multi-asset deposits, yield distribution, and asset whitelisting
 * @dev Handles multi-asset deposits with oracle conversion, yield distribution, and redemption controls
 * @dev Provides ERC4626-compatible functions for vaults (vault address must be passed as first parameter)
 * @dev Features:
 *      - Two-step treasury address transfer (setTreasury + acceptTreasury)
 *      - Fee transfers use FeeType enum (DepositFee, RedemptionFee, ManagementFee, PerformanceFee)
 *      - Redemption processing emits effectiveNav, burnShares, and gasFeeShares
 *      - Deposit share calculations optimized to work directly in 18 decimals
 *      - Events emitted from main functions (not helper methods) for better visibility
 */
contract Manager is AccessControl, IManager {
    using SafeERC20 for IERC20;
    using AccountingLib for uint256;
    using MathLib for uint256;
    using AddressLib for address;

    // ═══════════════════════════════════════════════════════════════════
    //                          STATE VARIABLES
    // ═══════════════════════════════════════════════════════════════════

    /// @notice Structure to hold all contract addresses
    struct Contracts {
        Registry registry;
        IFeatureRegistry featureRegistry;
        NAV navContract;
        IPriceOracle priceOracle;
    }

    /// @notice All contract addresses grouped together
    Contracts public contracts;

    /// @notice Treasury address (protocol treasury)
    address public treasury;

    /// @notice Pending treasury address (two-step transfer)
    address public pendingTreasury;

    /// @notice Whitelisted assets per vault: vault => asset => isWhitelisted
    /// @dev key: vault (address), nested key: asset (address), value: isWhitelisted (bool)
    mapping(address vault => mapping(address asset => bool isWhitelisted)) public isWhitelisted;

    /// @notice Redemption queue entry structure
    struct RedemptionQueueEntry {
        address owner; // the owner of the shares that are being redeemed
        address receiver; // the address that will receive the redemption assets (can be different from the owner)
        uint256 lockedShares; // the number of shares that are being redeemed
        uint256 navAtRequest; // the NAV at the time of the redemption request
        uint256 timestamp; // the timestamp of the redemption request
    }

    /// @notice Redemption queue per vault: vault => queue index => queue entry
    /// @dev key: vault (address), nested key: queueIndex (uint256), value: queueEntry (RedemptionQueueEntry)
    mapping(address vault => mapping(uint256 queueIndex => RedemptionQueueEntry queueEntry)) public redemptionQueues;

    /// @notice Next queue index per vault (monotonic counter, never decrements)
    /// @dev Incremented on each redemption request to ensure unique indices
    /// @dev key: vault (address), value: nextQueueIndex (uint256)
    mapping(address vault => uint256 nextQueueIndex) public nextQueueIndex;

    /// @notice Standard Debt per vault (redemption obligations in shares)
    /// @dev Standard Debt = Σ(locked_shares) - tracks redemption obligations in shares
    /// @dev key: vault (address), value: standardDebt (uint256)
    mapping(address vault => uint256 standardDebt) public standardDebt;

    /// @notice Maximum NAV change percentage per vault (18 decimals, e.g., 10e16 = 10%)
    /// @dev key: vault (address), value: maxNavChangePercent (uint256)
    mapping(address vault => uint256 maxNavChangePercent) public maxNavChangePercent;

    /**
     * @dev Storage gap for upgradeable contracts
     * CRITICAL: Update gap when adding/removing state variables
     * Current usage:
     * - contracts: 4 slots (struct with 4 fields)
     * - isWhitelisted: 1 slot (mapping)
     * - redemptionQueues: 1 slot (mapping)
     * - nextQueueIndex: 1 slot (mapping)
     * - standardDebt: 1 slot (mapping)
     * - treasury: 1 slot
     * - pendingTreasury: 1 slot
     * - maxNavChangePercent: 1 slot
     * - AccessControl parent: ~1 slot (administrator)
     * - Gap: 72 - 11 = 61 slots remaining
     * Note: _gap follows OpenZeppelin's standard pattern for upgradeable contracts
     * Note: userDeposits and totalDeposits are now stored in LimitsFeature contract
     */
    uint256[61] private _gap;

    // ═══════════════════════════════════════════════════════════════════
    //                             ERRORS
    // ═══════════════════════════════════════════════════════════════════
    // All errors are defined in Errors.sol library

    // ═══════════════════════════════════════════════════════════════════
    //                         INITIALIZATION
    // ═══════════════════════════════════════════════════════════════════

    /// @custom:oz-upgrades-unsafe-allow constructor
    constructor() {
        _disableInitializers();
    }

    /**
     * @notice Initialize the Manager contract
     * @param administrator_ Administrator contract address
     * @param registry_ Registry contract address
     * @param featureRegistry_ Feature registry contract address
     * @param navContract_ NAV contract address
     * @param priceOracle_ Price oracle contract address (can be address(0) initially)
     */
    function initialize(
        address administrator_,
        address registry_,
        address featureRegistry_,
        address navContract_,
        address priceOracle_
    ) external initializer {
        administrator_.requireNonZeroContract();
        registry_.requireNonZeroContract();
        featureRegistry_.requireNonZeroContract();
        navContract_.requireNonZeroContract();
        __AccessControl_init(administrator_);
        contracts = Contracts({
            registry: Registry(registry_),
            featureRegistry: IFeatureRegistry(featureRegistry_),
            navContract: NAV(navContract_),
            priceOracle: IPriceOracle(priceOracle_)
        });
    }

    // ═══════════════════════════════════════════════════════════════════
    //                            MODIFIERS
    // ═══════════════════════════════════════════════════════════════════

    // ═══════════════════════════════════════════════════════════════════
    //                      EXTERNAL WRITE FUNCTIONS
    // ═══════════════════════════════════════════════════════════════════

    /**
     * @notice Set all contract addresses at once (EMERGENCY ONLY)
     * @param registry_ Registry contract address
     * @param featureRegistry_ Feature registry contract address
     * @param navContract_ NAV contract address
     * @param priceOracle_ Price oracle contract address (can be address(0) initially)
     * @dev EMERGENCY FUNCTION: Used only in emergency situations to update contract addresses.
     * Generally, these addresses are set once during initialization and should not be changed.
     * This function allows emergency operators to update contract addresses in case of critical issues
     * such as contract upgrades or emergency migrations.
     */
    function setContracts(
        address registry_,
        address featureRegistry_,
        address navContract_,
        address priceOracle_
    ) external onlyEmergencyOperator {
        registry_.requireNonZeroContract();
        featureRegistry_.requireNonZeroContract();
        navContract_.requireNonZeroContract();
        contracts = Contracts({
            registry: Registry(registry_),
            featureRegistry: IFeatureRegistry(featureRegistry_),
            navContract: NAV(navContract_),
            priceOracle: IPriceOracle(priceOracle_)
        });
        emit ContractsSet(registry_, featureRegistry_, navContract_, priceOracle_);
    }

    // ═══════════════════════════════════════════════════════════════════
    //                      INTERNAL VIEW FUNCTIONS
    // ═══════════════════════════════════════════════════════════════════

    /**
     * @notice Validate greenlist for given addresses if greenlist feature is enabled
     * @param vault Vault address
     * @param address1 First address to validate
     * @param address2 Second address to validate
     * @dev Only checks greenlist if feature is enabled to avoid unnecessary gas costs
     */
    function _validateGreenlist(
        address vault,
        address address1,
        address address2
    ) internal view {
        // Check if greenlist feature is enabled for this vault
        bool greenlistEnabled = contracts.featureRegistry.isFeatureEnabled(
            vault,
            Constants.GREENLIST_FEATURE_ID
        );

        // This to avoid unnecessary gas costs if greenlist is not enabled
        if (greenlistEnabled) {
            // Get feature contract from feature registry
            address greenListContract = contracts.featureRegistry.getFeatureContract(
                Constants.GREENLIST_FEATURE_ID
            );

            if (
                !IGreenlistFeature(greenListContract).isUserGreenlisted(
                    vault,
                    address1
                )
            ) revert Errors.NotOnGreenlist(address1);
            if (
                !IGreenlistFeature(greenListContract).isUserGreenlisted(
                    vault,
                    address2
                )
            ) revert Errors.NotOnGreenlist(address2);
        }
    }

    /**
     * @notice Validate deposit inputs and vault/asset status
     * @param vault Vault address
     * @param asset Asset address
     * @param amount Amount of assets to deposit
     * @param receiver Address to receive shares
     */
    function _validateDeposit(
        address vault,
        address asset,
        uint256 amount,
        address receiver
    ) internal view {
        vault.requireNonZeroContract();
        asset.requireNonZero();
        receiver.requireNonZero();
        if (amount == 0) revert Errors.ZeroAmount();

        // Check vault is registered
        if (!contracts.registry.isVaultRegistered(vault))
            revert Errors.VaultNotRegistered(vault);

        // Check asset is whitelisted
        if (!isWhitelisted[vault][asset]) {
            revert Errors.AssetNotWhitelisted(vault, asset);
        }

        // Blacklist checks
        _notBlacklisted(msg.sender);
        _notBlacklisted(receiver);

        // Validate greenlist for sender and receiver
        _validateGreenlist(vault, msg.sender, receiver);

    }

    /**
     * @notice Validate redemption request inputs and vault/user status
     * @param vault Vault address
     * @param shares Amount of shares to redeem
     * @param receiver Address to receive redemption assets
     */
    function _validateRedeem(
        address vault,
        uint256 shares,
        address owner,
        address receiver
    ) internal view {
        vault.requireNonZeroContract();
        receiver.requireNonZero();
        if (shares == 0) revert Errors.ZeroAmount();

        // Blacklist checks: prevent blacklisted addresses from redeeming or receiving redemptions
        _notBlacklisted(owner);
        _notBlacklisted(receiver);
        _notBlacklisted(msg.sender);

        // Validate greenlist for owner and receiver
        _validateGreenlist(vault, owner, receiver);

        // Check redemptions are enabled
        if (!contracts.registry.isRedemptionEnabled(vault)) {
            revert Errors.RedemptionsDisabledForVault(vault);
        }

        // Check user has sufficient unlocked shares
        uint256 userBalance = IVault(vault).balanceOf(owner);
        if (userBalance < shares) {
            revert Errors.InsufficientShares(userBalance, shares);
        }
    }

    /**
     * @notice Get current NAV from NAV contract and validate it's initialized
     * @param vault Vault address
     * @return currentNav Current NAV (18 decimals)
     */
    function _getAndValidateNav(address vault) internal view returns (uint256 currentNav) {
        currentNav = contracts.navContract.getNav(vault);
        if (currentNav == 0) {
            revert Errors.NavNotInitialized(vault);
        }
    }

    /**
     * @notice Calculate total shares to mint for deposit (combines base asset, price, value, and shares calculation)
     * @param vault Vault address
     * @param asset Asset address being deposited
     * @param amount Amount of assets to deposit
     * @param currentNav Current NAV (18 decimals)
     * @return totalSharesToMint Total shares to mint before fees (18 decimals)
     * @return depositValueInBase Deposit value in base asset (18 decimals)
     */
    function _calculateDepositSharesFromAsset(
        address vault,
        address asset,
        uint256 amount,
        uint256 currentNav
    ) internal view returns (uint256 totalSharesToMint, uint256 depositValueInBase) {
        // Get and validate base asset
        address baseAsset = contracts.registry.baseAssets(vault);
        baseAsset.requireNonZero();

        uint256 depositPrice;
        bool priceValid;

        if (asset == baseAsset) {
            depositPrice = Constants.PRECISION;
            priceValid = true;
        }

        if (asset != baseAsset) {
            (depositPrice, priceValid) = contracts.priceOracle
                .getDepositPrice(asset, baseAsset);
            if (!priceValid || depositPrice == 0) {
                revert Errors.InvalidOraclePrice(asset, baseAsset, "INVALID_PRICE");
            }
        }

        // Calculate deposit value in base asset (18 decimals): m = q × P_asset,deposit
        // Work directly in 18 decimals to avoid unnecessary conversions
        uint8 assetDecimals = IERC20Metadata(asset).decimals(); // asset decimals

        // Scale amount to 18 decimals, then multiply by depositPrice (already 18 decimals)
        uint256 amountIn18Decimals = MathLib.scaleDecimals(amount, assetDecimals, 18);
        uint256 depositValueInBaseForShares = MathLib.mulDiv18(amountIn18Decimals, depositPrice);

        uint256 effectiveNav = _getMaxNavIfEnabled(vault, currentNav);

        // Calculate total shares to mint: ΔS = m / NAV (both in 18 decimals)
        totalSharesToMint = AccountingLib.calculateSharesToMint(depositValueInBaseForShares, effectiveNav);

        // Scale depositValueInBase to base asset decimals for limits validation
        depositValueInBase = MathLib.scaleDecimals(depositValueInBaseForShares, 18, IERC20Metadata(baseAsset).decimals());
    }


    /**
     * @notice Get effective NAV (max nav if enabled)
     * @param vault Vault address
     * @param currentNav Current NAV (18 decimals)
     */
    function _getMaxNavIfEnabled(address vault, uint256 currentNav) internal view returns (uint256 maxNav) {
        bool maxNavEnabled = contracts.featureRegistry.isFeatureEnabled(
            vault,
            Constants.MAX_NAV_FEATURE_ID
        );

        // If max nav feature is not enabled, return current nav - validation is already done in _getAndValidateNav
        if (!maxNavEnabled) {
            return currentNav;
        }

        // Get max nav from NAV contract
        maxNav = contracts.navContract.getStoredNav(vault);

        // If max nav is not initialized, return current nav -- since in the initializeNav function, we set the max nav to the current nav this should never happen, where as this is protection for any unforeseen issues
        if (maxNav == 0) {
            revert Errors.NavNotInitialized(vault);
        }

        // Max function to return the higher of the two navs
        return maxNav > currentNav ? maxNav : currentNav;
    }

    /**
     * @notice Validate redemption queue index and get entry
     * @param vault Vault address
     * @param queueIndex Queue index to validate
     * @return entry Redemption queue entry
     * @dev Performs common prechecks: vault validation, registration, entry existence, and blacklist checks
     */
    function _validateAndGetRedemptionEntry(
        address vault,
        uint256 queueIndex,
        bool isCancelRedemption
    ) internal view returns (RedemptionQueueEntry memory entry) {
        // Validate vault is non-zero and registered
        vault.requireNonZeroContract();
        if (!contracts.registry.isVaultRegistered(vault)) {
            revert Errors.VaultNotRegistered(vault);
        }

        // Check vault-level pause
        if (contracts.registry.vaultPaused(vault)) {
            revert Errors.VaultPaused(vault);
        }

        // Get and validate entry exists (owner is zero for never-assigned or deleted entries)
        entry = redemptionQueues[vault][queueIndex];
        if (entry.owner == address(0)) {
            revert Errors.InvalidQueueIndex(queueIndex);
        }

        // Blacklist check: prevent blacklisted addresses from processing redemptions
        _notBlacklisted(entry.owner);

        if (!isCancelRedemption) {
            _notBlacklisted(entry.receiver);
        }
    }

    /**
     * @notice Get redemption configuration (base asset and redemption source)
     * @param vault Vault address
     * @return baseAsset Base asset address (redemptions are always in base asset)
     * @return redemptionSource Redemption source address
     * @dev Redemptions are always processed in base asset, unlike deposits which can be in any whitelisted asset
     */
    function _getRedemptionConfig(
        address vault
    ) internal view returns (address baseAsset, address redemptionSource) {
        baseAsset = contracts.registry.baseAssets(vault);
        redemptionSource = contracts.registry.redemptionSources(vault);
        baseAsset.requireNonZero();
        redemptionSource.requireNonZero();
    }

    /**
     * @notice Calculate fees and net shares for deposits or redemptions
     * @param vault Vault address
     * @param asset Asset address (baseAsset for redemption, deposit asset for deposits)
     * @param shares Total shares before fees
     * @param isRedemption True for redemption fees, false for deposit fees
     * @return netShares Net shares after fees
     * @return feeShares Fee shares
     */
    function _calculateFees(
        address vault,
        address asset,
        uint256 shares,
        bool isRedemption
    ) internal view returns (uint256 netShares, uint256 feeShares) {
        Registry.AssetFeeConfig memory assetFeeConfig = contracts.registry.getAssetFeeConfig(
            vault,
            asset
        );
        uint256 feeRate = isRedemption ? assetFeeConfig.redemptionFee : assetFeeConfig.depositFee;
        (netShares, feeShares) = AccountingLib.calculateFee(shares, feeRate);
    }

    /**
     * @notice Calculate assets to transfer for redemption
     * @param netShares Net shares after fees (18 decimals)
     * @param effectiveNav Effective NAV (18 decimals)
     * @param baseAsset Base asset address (for decimal scaling)
     * @return assetsToTransfer Assets to transfer to user (in base asset decimals)
     * @dev Uses minimum of navAtLock and currentNav to protect users from NAV decreases
     * @dev Scales result from 18 decimals to base asset decimals
     */
    function _calculateRedemptionAssets(
        uint256 netShares,
        uint256 effectiveNav,
        address baseAsset
    ) internal view returns (uint256 assetsToTransfer) {
        // Calculate assets in 18 decimals (base asset decimals)
        uint256 assetsIn18Decimals = AccountingLib.calculateAssetsToRedeem(netShares, effectiveNav);

        // Scale from 18 decimals to base asset decimals
        uint8 baseAssetDecimals = IERC20Metadata(baseAsset).decimals();
        assetsToTransfer = MathLib.scaleDecimals(assetsIn18Decimals, 18, baseAssetDecimals);
    }

    /**
     * @notice Calculate effective NAV and assets to transfer for redemption
     * @param vault Vault address
     * @param entryNavAtRequest NAV at request time
     * @param currentNav Current NAV
     * @param netShares Net shares after gas fees
     * @param baseAsset Base asset address
     * @return effectiveNav Effective NAV to use
     * @return assetsToTransfer Assets to transfer to receiver
     */
    function _calculateRedemptionAmounts(
        address vault,
        uint256 entryNavAtRequest,
        uint256 currentNav,
        uint256 netShares,
        address baseAsset
    ) internal view returns (uint256 effectiveNav, uint256 assetsToTransfer) {
        // Check if MIN_NAV feature is enabled
        bool minNavEnabled = contracts.featureRegistry.isFeatureEnabled(
            vault,
            Constants.MIN_NAV_FEATURE_ID
        );

        if(minNavEnabled) {
            effectiveNav = entryNavAtRequest < currentNav ? entryNavAtRequest : currentNav;
        } else {
            effectiveNav = currentNav;
        }

        // Calculate assets to transfer
        assetsToTransfer = _calculateRedemptionAssets(
            netShares,
            effectiveNav,
            baseAsset
        );
    }

    /**
     * @notice Execute redemption processing: settlement, debt update, queue cleanup, and event emission
     * @param vault Vault address
     * @param entryOwner Owner of the redemption entry
     * @param entryReceiver Receiver of the redemption assets
     * @param entryLockedShares Locked shares amount
     * @param queueIndex Queue index of the redemption entry
     * @param baseAsset Base asset address
     * @param redemptionSource Redemption source address
     * @param assetsToTransfer Assets to transfer to receiver
     * @dev Handles all post-calculation operations for redemption processing
     */
    function _executeRedemptionProcessing(
        address vault,
        address entryOwner,
        address entryReceiver,
        uint256 entryLockedShares,
        uint256 queueIndex,
        address baseAsset,
        address redemptionSource,
        uint256 assetsToTransfer
    ) internal {
        // Unlock shares for the owner before burning
        IVault(vault).unlockShares(entryOwner, entryLockedShares);

        // Burn locked shares (all locked shares are burned)
        IVault(vault).burn(entryOwner, entryLockedShares);

        // Update Standard Debt: SD = SD - lockedShares
        if (standardDebt[vault] < entryLockedShares) {
            standardDebt[vault] = 0;
        } else {
            standardDebt[vault] = MathLib.safeSub(standardDebt[vault], entryLockedShares);
        }

        // Remove entry from queue (delete entry, keep index unique)
        delete redemptionQueues[vault][queueIndex];

        // Transfer assets from redemption source to receiver - moved to after the queue is removed to avoid reentrancy
        _transferAssets(baseAsset, redemptionSource, entryReceiver, assetsToTransfer);
    }

    /**
     * @notice Calculate redemption fees, charge fees, and lock net shares
     * @param vault Vault address
     * @param shares Amount of shares to redeem
     * @return netShares Net shares after fees (locked shares)
     * @dev Burns fee shares from user, mints to fee receiver, and locks net shares
     */
    function _chargeRedemptionFeesAndLockShares(
        address vault,
        address owner,
        uint256 shares
    ) internal returns (uint256 netShares) {
        // Get redemption configuration for fee calculation
        (address baseAsset, ) = _getRedemptionConfig(vault);
        address feeReceiver = contracts.registry.feeReceivers(vault);

        // Calculate redemption fees (fees are charged at request time)
        uint256 feeShares;

        if (owner == feeReceiver) {
            feeShares = 0;
            netShares = shares;
        } else {
            (netShares, feeShares) = _calculateFees(
                vault,
                baseAsset,
                shares,
                true // isRedemption = true
            );
        }

        // Spend allowance if caller is not the owner (before burning/locking shares)
        if (owner != msg.sender) {
            IVault(vault).spendAllowance(owner, msg.sender, shares);
        }

        // Mint fee shares directly to feeReceiver
        if (feeShares > 0) {
            IVault(vault).burn(owner, feeShares); // Burn fee shares from user's account
            feeReceiver.requireNonZero();
            IVault(vault).mint(feeReceiver, feeShares);
            emit FeeTransferred(vault, feeReceiver, feeShares, FeeType.RedemptionFee, baseAsset);
        }

        // Lock net shares (after fees are deducted)
        IVault(vault).lockShares(owner, netShares);
    }


    // ═══════════════════════════════════════════════════════════════════
    //                      EXTERNAL VIEW FUNCTIONS
    // ═══════════════════════════════════════════════════════════════════

    /**
     * @notice Check if an address is a registered vault (delegates to Registry)
     * @param vault Address to check
     * @return isRegistered True if vault is registered
     */
    function isVault(
        address vault
