    // ═══════════════════════════════════════════════════════════════════
    //                      INTERNAL WRITE FUNCTIONS
    // ═══════════════════════════════════════════════════════════════════

    function _transferAssets(
        address asset_,
        address from,
        address to,
        uint256 amount
    ) internal {
        asset_.requireNonZeroContract();
        to.requireNonZero();
        from.requireNonZero();
        if (from == to) revert Errors.SameAddress();
        if (amount == 0) revert Errors.ZeroAmount();

        // Transfer assets from sender to recipient
        IERC20(asset_).safeTransferFrom(from, to, amount);
    }

    /**
     * @notice Validate deposit limits in LimitsFeature (if enabled)
     * @param vault Vault address
     * @param receiver Address of the receiver (user receiving shares)
     * @param depositValueInBase Deposit value in base asset (18 decimals)
     * @dev Called before _executeDeposit to follow Checks-Effects-Interactions pattern
     * @dev Validates limits based on current vault balance and total supply
     */
    function _validateDepositLimits(
        address vault,
        address receiver,
        uint256 depositValueInBase
    ) internal view {
        // Check if limits feature is enabled for this vault
        bool limitsEnabled = contracts.featureRegistry.isFeatureEnabled(
            vault,
            Constants.LIMITS_FEATURE_ID
        );
        if (limitsEnabled) {
            // Get limits feature contract
            address limitsContract = contracts.featureRegistry.getFeatureContract(
                Constants.LIMITS_FEATURE_ID
            );

            // Validate deposit against limits (calculates from vault balance and total supply)
            ILimitsFeature(limitsContract).validateDeposit(
                vault,
                receiver,
                depositValueInBase
            );
        }
    }

    /**
     * @notice Execute deposit: transfer assets, mint shares with fees, emit event
     * @param vault Vault address
     * @param asset Asset address
     * @param amount Amount of assets to deposit
     * @param netShares Net shares to mint to receiver (after fees)
     * @param feeShares Fee shares to mint to feeStore
     * @param receiver Address to receive shares
     * @param referralCode Optional referral partner code (keccak hash, bytes32)
     */
    function _executeDeposit(
        address vault,
        address asset,
        uint256 amount,
        uint256 netShares,
        uint256 feeShares,
        address receiver,
        bytes32 referralCode
    ) internal {
        // Transfer assets to the vault deposit receiver
        _transferAssets(
            asset,
            msg.sender,
            contracts.registry.depositRecipients(vault),
            amount
        );

        // Mint fee shares directly to feeReceiver if applicable
        if (feeShares > 0) {
            address feeReceiver = contracts.registry.feeReceivers(vault);
            feeReceiver.requireNonZero();
            IVault(vault).mint(feeReceiver, feeShares);

            emit FeeTransferred(vault, feeReceiver, feeShares, FeeType.DepositFee, asset);
        }

        // Mint net shares to receiver (after fees)
        IVault(vault).mint(receiver, netShares);

        // Emit deposit event
        emit Deposit(vault, asset, msg.sender, receiver, amount, netShares, feeShares, referralCode);
    }

    // ═══════════════════════════════════════════════════════════════════
    //                      EXTERNAL WRITE FUNCTIONS
    // ═══════════════════════════════════════════════════════════════════

    /**
     * @notice Whitelist or blacklist an asset for a vault
     * @param vault Vault address
     * @param asset Asset address
     * @param status True to whitelist, false to blacklist
     */
    function setAssetWhitelist(
        address vault,
        address asset,
        bool status
    ) external override onlyOperator {
        asset.requireNonZero();
        isWhitelisted[vault][asset] = status;
        emit AssetWhitelisted(vault, asset, status);
    }

    /**
     * @notice Disable asset whitelist for a vault
     * @param vault Vault address
     * @param asset Asset address
     * @dev This is curator only function. Operator can whitelist/blacklist assets using setAssetWhitelist function.
     */
    function disableAsset(
        address vault,
        address asset
    ) external override {
        contracts.registry.onlyCuratorForVault(vault, msg.sender);
        isWhitelisted[vault][asset] = false;
        emit AssetWhitelisted(vault, asset, false);
    }    

    /**
     * @notice Deposit assets into a vault (supports multi-asset deposits)
     * @param vault Vault address
     * @param asset Asset address (must be whitelisted, can be different from vault base asset)
     * @param amount Amount of assets to deposit
     * @param receiver Address to receive shares
     * @param referralCode Optional referral partner code (keccak hash, bytes32)
     * @return shares Amount of shares minted (net of fees)
     * @dev Implements deposit model from whitepaper Section 4.1
     * @dev Deposits can be in any whitelisted asset, converted to base asset value via oracle
     * @dev referralCode is optional and can be bytes32(0) if not provided
     */
    function deposit(
        address vault,
        address asset,
        uint256 amount,
        address receiver,
        uint256 minShares,
        bytes32 referralCode
    ) external override whenNotPaused nonReentrant returns (uint256 shares) {
        // Check vault-level pause
        if (contracts.registry.vaultPaused(vault)) {
            revert Errors.VaultPaused(vault);
        }

        // Validate deposit inputs
        _validateDeposit(vault, asset, amount, receiver);

        // Get current NAV (must be initialized before deposit)
        uint256 currentNav = _getAndValidateNav(vault);

        // Calculate total shares to mint from asset (handles base asset, price, value, and shares)
        (uint256 totalSharesToMint, uint256 depositValueInBase) = _calculateDepositSharesFromAsset(
            vault,
            asset,
            amount,
            currentNav
        );

        // Calculate deposit fee: Fee_asset = m × df_f
        (uint256 netShares, uint256 feeShares) = _calculateFees(
            vault,
            asset,
            totalSharesToMint,
            false // isRedemption = false
        );

        if (netShares < minShares) { // Slippage protection
            revert Errors.InsufficientShares(netShares, minShares);
        }

        // Validate deposit limits (before minting shares)
        // Note: validateDeposit calculates from current vault balance/supply
        // The new shares will be minted after validation, so we validate against current state + new deposit
        _validateDepositLimits(vault, receiver, depositValueInBase);

        // Execute deposit: transfer assets, mint shares
        _executeDeposit(
            vault,
            asset,
            amount,
            netShares,
            feeShares,
            receiver,
            referralCode
        );

        return netShares;
    }

    /**
     * @notice Request redemption by locking shares and adding to queue
     * @param vault Vault address
     * @param shares Amount of shares to redeem
     * @param owner Owner of the shares (must have sufficient balance, or caller must have allowance)
     * @param receiver Address to receive the redemption assets 
     * @dev Implements redemption request model from whitepaper Section 4.2
     * @dev If owner != msg.sender, caller must have allowance to spend owner's shares
     */
    function requestRedemption(
        address vault,
        uint256 shares,
        address owner,
        address receiver,
        bytes32 referralCode
    ) external whenNotPaused nonReentrant {
        // Check vault-level pause
        if (contracts.registry.vaultPaused(vault)) {
            revert Errors.VaultPaused(vault);
        }

        // Validate redemption inputs
        _validateRedeem(vault, shares, owner, receiver);

        // Get current NAV (validated to ensure vault is initialized) 
        uint256 currentNav = _getAndValidateNav(vault);

        // Calculate redemption fees, charge fees, and lock net shares
        uint256 netShares = _chargeRedemptionFeesAndLockShares(vault, owner, shares);

        // Create queue entry (lockedShares is netShares after fees)
        RedemptionQueueEntry memory entry = RedemptionQueueEntry({
            owner: owner,
            receiver: receiver,
            lockedShares: netShares,
            navAtRequest: currentNav,
            timestamp: block.timestamp
        });

        // Add to queue
        uint256 queueIndex = nextQueueIndex[vault];
        redemptionQueues[vault][queueIndex] = entry;
        nextQueueIndex[vault] = MathLib.safeAdd(nextQueueIndex[vault], 1);

        // Update Standard Debt: SD = SD + lockedShares (netShares)
        standardDebt[vault] = MathLib.safeAdd(standardDebt[vault], netShares);

        emit RedemptionRequested(vault, owner, queueIndex, shares, receiver, referralCode);
    }

    /**
     * @notice Cancel a redemption request
     * @param vault Vault address
     * @param queueIndex Index of redemption request to cancel
     * @dev Implements redemption cancellation model from whitepaper Section 4.2
     */
    function cancelRedemption(
        address vault,
        uint256 queueIndex
    ) external override nonReentrant {

        // Validate and get redemption entry
        RedemptionQueueEntry memory entry = _validateAndGetRedemptionEntry(vault, queueIndex, true);

        // Spend allowance if caller is not the owner (before unlocking shares)
        if (entry.owner != msg.sender) {
            IVault(vault).spendAllowance(entry.owner, msg.sender, entry.lockedShares);
        }

        // Unlock shares for the owner (shares belong to owner, not necessarily msg.sender)
        IVault(vault).unlockShares(entry.owner, entry.lockedShares);

        // Update Standard Debt: SD = SD - lockedShares
        if (standardDebt[vault] < entry.lockedShares) {
            standardDebt[vault] = 0;
        } else {
            standardDebt[vault] = MathLib.safeSub(standardDebt[vault], entry.lockedShares);
        }

        // Remove from queue (delete entry, keep index unique)
        delete redemptionQueues[vault][queueIndex];

        emit RedemptionCancelled(vault, entry.owner, queueIndex, entry.lockedShares, entry.receiver);
    }

    /**
     * @notice Process redemption from queue (only operator)
     * @param vault Vault address
     * @param queueIndex Index of redemption request to process
     * @param gasFeeShares Gas fees in shares to deduct from redemption
     * @dev Implements redemption settlement model from whitepaper Section 4.2
     * @dev Redemptions are always in base asset (unlike deposits which can be in any whitelisted asset)
     * @dev Gas fees are deducted from netShares and transferred to treasury
     */
    function processRedemption(
        address vault,
        uint256 queueIndex,
        uint256 gasFeeShares
    ) external override onlyOperator nonReentrant {
        // Validate and get redemption entry (includes vault validation, registration, entry existence, and blacklist checks)
        RedemptionQueueEntry memory entry = _validateAndGetRedemptionEntry(vault, queueIndex, false);

        // Extract entry fields to reduce stack depth
        address entryOwner = entry.owner;
        address entryReceiver = entry.receiver;
        uint256 entryLockedShares = entry.lockedShares;
        uint256 entryNavAtRequest = entry.navAtRequest;

        // Get current NAV (must be initialized)
        uint256 currentNav = _getAndValidateNav(vault);

        // Get redemption configuration
        (address baseAsset, address redemptionSource) = _getRedemptionConfig(vault);

        // Deduct gas fee shares from netShares (entryLockedShares is already netShares after fees)
        if (entryLockedShares < gasFeeShares) {
            revert Errors.InsufficientShares(entryLockedShares, gasFeeShares);
        }
        uint256 netShares = entryLockedShares - gasFeeShares;

        // Transfer gas fee shares to treasury
        if (gasFeeShares > 0) {
            treasury.requireNonZero();
            IVault(vault).mint(treasury, gasFeeShares);
        }

        // Calculate effective NAV and assets to transfer in helper function
        (uint256 effectiveNav, uint256 assetsToTransfer) = _calculateRedemptionAmounts(
            vault,
            entryNavAtRequest,
            currentNav,
            netShares,
            baseAsset
        );

        // Execute redemption processing (pass extracted values instead of full struct)
        _executeRedemptionProcessing(
            vault,
            entryOwner,
            entryReceiver,
            entryLockedShares,
            queueIndex,
            baseAsset,
            redemptionSource,
            assetsToTransfer
        );

        // Emit all events in main method
        emit RedemptionProcessed(
            vault,
            entryOwner,
            entryReceiver,
            queueIndex,
            assetsToTransfer,
            effectiveNav,
            entryLockedShares,
            gasFeeShares
        );
    }

    /**
     * @notice Set price oracle contract address
     * @param priceOracle_ New price oracle address
     * @dev This is operator only function. Curator can set price oracle using setPriceOracle function.
     */
    function setPriceOracle(address priceOracle_) external onlyEmergencyOperator {
        priceOracle_.requireNonZeroContract();
        contracts.priceOracle = IPriceOracle(priceOracle_);
        emit PriceOracleSet(priceOracle_);
    }

    /**
     * @notice Validate NAV update guardrails
     * @param vault Vault address
     * @param newNav New NAV value (18 decimals)
     * @param managementFeeShares Management fee amount in shares (18 decimals)
     * @param performanceFeeShares Performance fee amount in shares (18 decimals)
     * @dev Validates NAV change percentage and fee amounts against guardrails
     */
    function _validateNavUpdateGuardrails(
        address vault,
        uint256 newNav,
        uint256 managementFeeShares,
        uint256 performanceFeeShares
    ) internal view {
        uint256 currentNav = contracts.navContract.getNav(vault);
        uint256 totalSupply = IVault(vault).totalSupply();

        // Guardrail: Validate NAV change percentage (skip if guardrail disabled)
        uint256 maxNavChangePercentGuardrail = maxNavChangePercent[vault];
        if (maxNavChangePercentGuardrail > 0) {
            uint256 navChangePercent = MathLib.absDeviation(newNav, currentNav);
            if (navChangePercent > maxNavChangePercentGuardrail) {
                revert Errors.ExcessiveDeviation(Constants.OP_NAV_CHANGE, navChangePercent, maxNavChangePercentGuardrail);
            }
        }

        // Get last vesting start time (time when last NAV update occurred)
        (, , uint256 vestingStart, ) = contracts.navContract.getVestingParams(vault);
        uint256 timeElapsed = vestingStart == 0 ? 0 : MathLib.safeSub(block.timestamp, vestingStart);

        // Guardrail: Validate fee amounts against configured fee rates from registry
        (uint256 managementFeeWithBuffer, uint256 performanceFeeWithBuffer) = contracts.registry.getFeesWithBuffer(vault);

        // Calculate expected management fee based on time elapsed since last vesting start
        // Formula: (totalSupply * managementFeeRate * timeElapsed) / (PRECISION * SECONDS_PER_YEAR)
        // Management fee is calculated based on current NAV (before update), so no conversion needed
        // Use MathLib functions for safe arithmetic
        uint256 maxManagementFeeShares = timeElapsed == 0 
            ? 0 
            : MathLib.safeDiv(
                MathLib.safeMul(
                    MathLib.safeMul(totalSupply, managementFeeWithBuffer),
                    timeElapsed
                ),
                MathLib.safeMul(Constants.PRECISION, Constants.SECONDS_PER_YEAR)
                );

        if (managementFeeShares > maxManagementFeeShares) {
            revert Errors.ExcessiveDeviation(Constants.OP_MANAGEMENT_FEE, managementFeeShares, maxManagementFeeShares);
        }

        // Performance fees are only charged on NAV appreciation above the high water mark
        uint256 highWaterMark = contracts.navContract.getHighWaterMark(vault);
        // Only consider NAV increase above high water mark for performance fee calculation
        uint256 navIncreaseAboveHwm = newNav > highWaterMark ? MathLib.safeSub(newNav, highWaterMark) : 0;

        if (navIncreaseAboveHwm > 0) {
            // Calculate asset value increase above HWM: (navIncreaseAboveHwm * totalSupply) / PRECISION
            // This gives us the asset value increase in asset terms (18 decimals)
            // Use MathLib.mulDiv18 for precision math
            uint256 assetValueIncrease = MathLib.mulDiv18(navIncreaseAboveHwm, totalSupply);

            // Calculate expected performance fee in asset terms: (assetValueIncrease * performanceFeeRate) / PRECISION
            // This is the performance fee amount in asset value (18 decimals)
            // Use MathLib.percentageOf for protocol-favorable rounding
            uint256 maxPerformanceFeeInAssets = MathLib.percentageOf(assetValueIncrease, performanceFeeWithBuffer);
            maxPerformanceFeeInAssets = MathLib.divPrecision(maxPerformanceFeeInAssets, MathLib.safeSub(Constants.HUNDRED_PERCENT, performanceFeeWithBuffer));

            // Convert expected performance fee from asset terms to share terms for comparison
            // Formula: shares = (assets * PRECISION) / nav
            // We use newNav since that's the NAV we're updating to
            // Use MathLib.divPrecision for precision division
            uint256 maxPerformanceFeeInShares = MathLib.divPrecision(maxPerformanceFeeInAssets, newNav);

            // Compare performance fee (in shares) with expected performance fee (in shares)
            if (performanceFeeShares > maxPerformanceFeeInShares) {
                revert Errors.ExcessiveDeviation(Constants.OP_PERFORMANCE_FEE, performanceFeeShares, maxPerformanceFeeInShares);
            }
        } else {
            // If NAV didn't increase above high water mark, performance fee should be zero
            if (performanceFeeShares > 0) {
                revert Errors.ExcessiveDeviation(Constants.OP_PERFORMANCE_FEE, performanceFeeShares, 0);
            }
        }
    }

    /**
     * @notice Update NAV and mint management/performance fees (only operator)
     * @param vault Vault address
     * @param newNav New NAV value (18 decimals)
     * @param vestingEndTime Vesting end timestamp
     * @param managementFee Management fee amount in shares (18 decimals)
     * @param performanceFee Performance fee amount in shares (18 decimals)
     */
    function updateNav(
        address vault,
        uint256 newNav,
        uint256 vestingEndTime,
        uint256 managementFee,
        uint256 performanceFee
    ) external onlyOperator {
        vault.requireNonZeroContract();

        // Check for zero NAV before validation (prevents division by zero in validation)
        if (newNav == 0) revert Errors.ZeroAmount();

        // Validate all guardrails
        _validateNavUpdateGuardrails(vault, newNav, managementFee, performanceFee);

        // require vestingEndTime to be in the future
        // When the nav is negative, veesting time would be current block timestamp - no vesting in case of loss
        if (vestingEndTime < block.timestamp) { 
            revert Errors.InvalidTime(vestingEndTime);
        }

        // Update NAV in NAV contract (includes vesting params and HWM update)
        contracts.navContract.updateNav(vault, newNav, vestingEndTime);

        // Mint management fee shares to treasury
        if (managementFee > 0) {
            treasury.requireNonZero();
            IVault(vault).mint(treasury, managementFee);
        }

        // Mint performance fee shares to vault fee receiver
        if (performanceFee > 0) {
            address feeReceiver = contracts.registry.feeReceivers(vault);
            feeReceiver.requireNonZero();
            IVault(vault).mint(feeReceiver, performanceFee);
        }

        // Emit NAV updated event
        emit NAVUpdated(
            vault,
            newNav,
            vestingEndTime,
            managementFee,
            performanceFee
        );
    }

    /**
     * @notice Set maximum NAV change percentage guardrail (only operator)
     * @param maxNavChangePercent_ Maximum NAV change percentage (18 decimals, e.g., 10e16 = 10%)
     * @dev Set to 0 to disable the guardrail
     */
    function setMaxNavChangePercent(address vault, uint256 maxNavChangePercent_) external onlyEmergencyOperator {
        vault.requireNonZeroContract();
        maxNavChangePercent[vault] = maxNavChangePercent_;
        emit MaxNavChangePercentUpdated(vault, maxNavChangePercent_);
    }


    /**
     * @notice Get the base asset address for a vault
     * @param vault Vault address
     * @return asset Base asset address
     */
    function getVaultAsset(address vault) external view override returns (address asset) {
        return contracts.registry.getBaseAsset(vault);
    }

    /**
     * @notice Convert shares to assets for a vault using current NAV
     * @param vault Vault address
     * @param shares Amount of shares to convert (18 decimals)
     * @param isRedemption True if redemption, false if deposit
     * @return assets Amount of assets (in base asset decimals)
     */
    function convertVaultSharesToAssets(
        address vault,
        uint256 shares,
        bool isRedemption
    ) external view override returns (uint256 assets) {
        uint256 currentNav = _getAndValidateNav(vault);
        if (!isRedemption) {
            currentNav = _getMaxNavIfEnabled(vault, currentNav);
        }

        // Calculate assets in 18 decimals (base asset decimals)
        uint256 assetsIn18Decimals = AccountingLib.calculateAssetsToRedeem(shares, currentNav);

        // Get base asset from Registry to scale to correct decimals
        address baseAsset = contracts.registry.getBaseAsset(vault);

        // Scale from 18 decimals to base asset decimals
        uint8 baseAssetDecimals = IERC20Metadata(baseAsset).decimals();

        assets = MathLib.scaleDecimals(assetsIn18Decimals, 18, baseAssetDecimals); // vaults shares are always 18 decimals
    }

    /**
     * @notice Convert assets to shares for a vault using current NAV
     * @param vault Vault address
     * @param assets Amount of assets to convert (in base asset decimals)
     * @param isRedemption True if redemption, false if deposit
     * @return shares Amount of shares (18 decimals)
     */
    function convertVaultAssetsToShares(
        address vault,
        uint256 assets,
        bool isRedemption
    ) external view override returns (uint256 shares) {
        uint256 currentNav = _getAndValidateNav(vault);
        if (!isRedemption) {
            currentNav = _getMaxNavIfEnabled(vault, currentNav);
        }

        // Get base asset from Registry to scale from correct decimals
        address baseAsset = contracts.registry.getBaseAsset(vault);
        uint8 baseAssetDecimals = IERC20Metadata(baseAsset).decimals();

        // Scale assets from base asset decimals to 18 decimals
        uint256 assetsIn18Decimals = MathLib.scaleDecimals(assets, baseAssetDecimals, 18); // vault shares are always 18 decimals

        // Calculate shares: shares = assets / NAV (both in 18 decimals)
        shares = AccountingLib.calculateSharesToMint(assetsIn18Decimals, currentNav);
    }

    /**
     * @notice Get total assets managed by a vault (ERC4626-compatible)
     * @param vault Vault address
     * @return Total assets in base asset (in base asset decimals)
     * @dev Reuses convertVaultSharesToAssets to calculate total assets
     * @dev Returns 0 if NAV is not initialized or totalSupply is 0
     */
    function totalAssets(address vault) external view returns (uint256) {
        // Get total supply of vault shares
        uint256 totalShares = IVault(vault).totalSupply();
        if (totalShares == 0) return 0;

        // Reuse convertVaultSharesToAssets to calculate total assets
        // Since we are calculating total assets at the current NAV
        return this.convertVaultSharesToAssets(vault, totalShares, true);
    }

    /**
     * @notice Check if a vault is paused (checks both vault-level and global pause)
     * @param vault Vault address
     * @return paused True if vault is paused or global pause is active
     */
    function isVaultPaused(address vault) external view override returns (bool paused) {
        return contracts.registry.isVaultPaused(vault);
    }


    /**
     * @notice Set pending treasury address (two-step transfer)
     * @param treasury_ New treasury address (must accept to complete transfer)
     */
    function setTreasury(address treasury_) external onlyOperator {
        treasury_.requireNonZero();
        pendingTreasury = treasury_;
        emit TreasuryPending(treasury_);
    }

    /**
     * @notice Accept treasury change (two-step transfer)
     * @dev Can only be called by the pending treasury address
     */
    function acceptTreasury() external {
        address pending = pendingTreasury;
        if (msg.sender != pending) { // mes.sender will always be non-zero hence there is no need for validing the zero address
            revert Errors.Unauthorized(msg.sender, bytes32(0));
        }

        treasury = pending;
        pendingTreasury = address(0);

        emit TreasuryUpdated(pending);
    }

    /**
     * @notice Calculate fees for a vault
     * @param vault Vault address
     * @param asset Asset address
     * @param amount Amount of assets
     * @param isRedemption True if redemption, false if deposit
     * @return netAmount Net amount after fees ( in the @param amount terms)
     * @return feeAmount Fee amount ( in the @param amount terms)
     */
    function calculateFees(address vault, address asset, uint256 amount, bool isRedemption) external view override returns (uint256 netAmount, uint256 feeAmount) {
        return _calculateFees(vault, asset, amount, isRedemption);
    }
}

