abstract contract AccessControl is
    Initializable,
    ReentrancyGuardTransient,
    IAccessControl
{
    using SafeERC20 for IERC20;
    // ═══════════════════════════════════════════════════════════════════
    //                          STATE VARIABLES
    // ═══════════════════════════════════════════════════════════════════

    /// @notice Administrator contract address for role management
    address public administrator;

    // ═══════════════════════════════════════════════════════════════════
    //                         STORAGE GAP
    // ═══════════════════════════════════════════════════════════════════

    // Note: Events are defined in IAccessControl interface

    // ═══════════════════════════════════════════════════════════════════
    //                             ERRORS
    // ═══════════════════════════════════════════════════════════════════
    // All errors are defined in Errors.sol library

    // ═══════════════════════════════════════════════════════════════════
    //                            MODIFIERS
    // ═══════════════════════════════════════════════════════════════════

    /**
     * @notice Restricts access to owner of Administrator contract
     */
    modifier onlyOwner() {
        _onlyOwner();
        _;
    }

    /**
     * @notice Restricts access to operator role holders
     */
    modifier onlyOperator() virtual {
        _onlyOperator();
        _;
    }

    /**
     * @notice Restricts access to signer role holders
     */
    modifier onlySigner() {
        _onlySigner();
        _;
    }

    /**
     * @notice Restricts access to emergency operator role holders
     * @dev Used for critical emergency setter functions that are generally set once and not reset
     */
    modifier onlyEmergencyOperator() {
        _onlyEmergencyOperator();
        _;
    }

    /**
     * @notice Prevents execution when contract is paused (centralized via Administrator)
     * @dev Checks pause status from Administrator contract for centralized pause control
     * @dev All contracts MUST use this modifier for pause functionality
     * @dev Follows OpenZeppelin naming convention
     */
    modifier whenNotPaused() {
        _notPaused();
        _;
    }

    /**
     * @notice Prevents blacklisted addresses from executing functions
     * @param user Address to check against blacklist
     */
    modifier notBlacklisted(address user) {
        _notBlacklisted(user);
        _;
    }

    // ═══════════════════════════════════════════════════════════════════
    //                         INITIALIZATION
    // ═══════════════════════════════════════════════════════════════════

    /**
     * @notice Initialize the access control with administrator address
     * @param _administrator Address of the administrator contract
     * @dev ReentrancyGuardTransient uses transient storage (EIP-1153) so no init needed
