        address _administrator
    ) internal onlyInitializing {
        AddressLib.requireNonZeroContract(_administrator);
        administrator = _administrator;
        emit AdministratorSet(address(0), _administrator);
    }

    // ═══════════════════════════════════════════════════════════════════
    //                      INTERNAL VIEW FUNCTIONS
    // ═══════════════════════════════════════════════════════════════════

    /**
     * @notice Internal function to check owner
     * @dev Checks if caller is the owner of the Administrator contract
     */
    function _onlyOwner() internal view {
        address owner_ = Ownable2StepUpgradeable(administrator).owner();
        if (msg.sender != owner_) {
            revert Errors.UnauthorizedCaller();
        }
    }

    /**
     * @notice Internal function to check operator role
     */
    function _onlyOperator() internal view virtual {
        if (!IRole(administrator).hasRole(Roles.OPERATOR_ROLE, msg.sender)) {
            revert Errors.Unauthorized(msg.sender, Roles.OPERATOR_ROLE);
        }
    }

    /**
     * @notice Internal function to check signer role
     */
    function _onlySigner() internal view {
        if (!IRole(administrator).hasRole(Roles.SIGNER_ROLE, msg.sender)) {
            revert Errors.Unauthorized(msg.sender, Roles.SIGNER_ROLE);
        }
    }

    /**
     * @notice Internal function to check emergency operator role
     */
    function _onlyEmergencyOperator() internal view {
        if (!IRole(administrator).hasRole(Roles.EMERGENCY_OPERATOR_ROLE, msg.sender)) {
            revert Errors.Unauthorized(msg.sender, Roles.EMERGENCY_OPERATOR_ROLE);
        }
