        bytes32 role,
        address account
    ) internal view returns (bool hasRole) {
        return IRole(administrator).hasRole(role, account);
    }

    /**
     * @notice Internal function to require specific role
     * @param role The role required
     * @param account The account that must have the role
     */
    function _requireRole(bytes32 role, address account) internal view {
        if (!_hasRole(role, account)) {
            revert Errors.Unauthorized(account, role);
        }
    }

    /**
     * @notice Internal function to check if caller has signer role
     * @param account The account to check role for
     * @return hasSignerRole True if account has signer role
     */
    function _hasSignerRole(address account) internal view returns (bool hasSignerRole) {
        return IRole(administrator).hasRole(Roles.SIGNER_ROLE, account);
    }

    /**
     * @notice Internal function to require signer role
     * @param account The account that must have signer role
     */
    function _requireSignerRole(address account) internal view {
        if (!_hasSignerRole(account)) {
            revert Errors.Unauthorized(account, Roles.SIGNER_ROLE);
        }
    }

    // ═══════════════════════════════════════════════════════════════════
    //                      EXTERNAL VIEW FUNCTIONS
    // ═══════════════════════════════════════════════════════════════════

    /**
     * @notice Returns the paused status of this contract from Administrator
     * @dev Checks centralized global pause status from Administrator contract
     * @return isPaused True if contract is paused
     */
    function paused() public view returns (bool isPaused) {
        if (administrator == address(0)) return true; // Stop contract if administrator not set
        isPaused = Administrator(administrator).isGloballyPaused();
    }

    /**
     * @notice Returns the blacklist status of an address from Administrator
     * @dev Checks centralized blacklist status from Administrator contract
     * @param user Address to check
     * @return blacklisted True if address is blacklisted
     */
    function isBlacklisted(
        address user
    ) public view returns (bool blacklisted) {
        if (administrator == address(0)) return true; // Stop contract if administrator not set
        blacklisted = IBlackList(administrator).isBlackListed(user);
    }

    // ═══════════════════════════════════════════════════════════════════
    //                      INTERNAL WRITE FUNCTIONS
    // ═══════════════════════════════════════════════════════════════════

    // (No internal write functions currently)

    // ═══════════════════════════════════════════════════════════════════
    //                      EXTERNAL WRITE FUNCTIONS
    // ═══════════════════════════════════════════════════════════════════

    /**
     * @notice Set the administrator contract address
     * @param _administrator Address of the new administrator contract
     */
    function setAdministrator(address _administrator) external onlyOwner {
        AddressLib.requireNonZeroContract(_administrator);

        administrator = _administrator;
        emit AdministratorSet(msg.sender, _administrator);
    }

    /**
     * @notice Rescue ERC20 tokens locked in this contract
     * @dev Allows admin to recover tokens accidentally sent to this contract
     * @param token Token address to rescue (address(0) for native ETH)
     * @param to Address to send rescued tokens to
     * @param amount Amount of tokens to rescue (0 for full balance)
     */
    function rescueTokens(
        address token,
        address to,
        uint256 amount
    ) external onlyEmergencyOperator nonReentrant {
        if (to == address(0)) revert Errors.ZeroAddress();

        if (token == address(0)) {
            // Rescue native ETH
            uint256 balance = address(this).balance;
            uint256 rescueAmount = amount == 0 ? balance : amount;
            if (rescueAmount == 0) revert Errors.ZeroAmount();
            if (rescueAmount > balance) {
                revert Errors.InsufficientBalance(balance, rescueAmount);
            }

            (bool success, ) = payable(to).call{value: rescueAmount}("");
            if (!success) revert Errors.TransferFailed();

            emit TokensRescued(address(0), to, rescueAmount);
        } else {
            // Rescue ERC20 tokens
            uint256 balance = IERC20(token).balanceOf(address(this));
            uint256 rescueAmount = amount == 0 ? balance : amount;
            if (rescueAmount == 0) revert Errors.ZeroAmount();
            if (rescueAmount > balance) {
                revert Errors.InsufficientBalance(balance, rescueAmount);
            }

            IERC20(token).safeTransfer(to, rescueAmount);
            emit TokensRescued(token, to, rescueAmount);
        }
    }
}

