import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {IEvents} from "./IEvents.sol";

/**
 * @title IVault
 * @author YieldFi Team
 * @notice Interface for YieldFi v3 Vault contract
 * @dev Vault is a pure ERC20Upgradeable token. All vault logic is handled by Manager contract.
 */
interface IVault is IERC20, IEvents {

    // ═══════════════════════════════════════════════════════════════════
    //                        ADMIN FUNCTIONS
    // ═══════════════════════════════════════════════════════════════════

    /**
     * @notice Mint tokens (only callable by Operator)
     * @param to Address to receive tokens
     * @param amount Amount of tokens to mint
     */
    function mint(address to, uint256 amount) external;

    /**
     * @notice Burn tokens (only callable by Operator)
     * @param from Address to burn tokens from
     * @param amount Amount of tokens to burn
     */
    function burn(address from, uint256 amount) external;

    /**
     * @notice Set vault token name and symbol
     * @param newName New vault token name
     * @param newSymbol New vault token symbol
     */
    function setNameAndSymbol(
        string calldata newName,
        string calldata newSymbol
    ) external;

    /**
     * @notice Lock shares for a user (only callable by Operator)
     * @param user Address to lock shares for
     * @param amount Amount of shares to lock
     */
    function lockShares(address user, uint256 amount) external;

    /**
     * @notice Unlock shares for a user (only callable by Operator)
     * @param user Address to unlock shares for
     * @param amount Amount of shares to unlock
     */
    function unlockShares(address user, uint256 amount) external;

    /**
     * @notice Spender allowance for a user
     * @param owner Owner address
     * @param spender Spender address
     * @param amount Amount of allowance to spend
     */
    function spendAllowance(address owner, address spender, uint256 amount) external;

    // ═══════════════════════════════════════════════════════════════════
    //                      EXTERNAL VIEW FUNCTIONS
    // ═══════════════════════════════════════════════════════════════════

    /**
     * @notice Get locked shares for a user
     * @param user Address of the user
     * @return locked Amount of locked shares
     */
    function lockedShares(address user) external view returns (uint256 locked);

    /**
     * @notice Get the base asset address for this vault
     * @return asset Base asset address
     * @dev Returns the base asset via Manager pass-through function
     */
    function asset() external view returns (address);

    /**
     * @notice Convert shares to assets using current NAV
     * @param shares Amount of shares to convert (18 decimals)
     * @return assets Amount of assets (in base asset decimals)
     * @dev Uses Manager pass-through function to calculate asset value
     */
    function convertToAssets(uint256 shares) external view returns (uint256 assets);

    /**
     * @notice Convert assets to shares using current NAV
     * @param assets Amount of assets to convert (in base asset decimals)
     * @return shares Amount of shares (18 decimals)
     * @dev ERC4626-compatible conversion function
     */
    function convertToShares(uint256 assets) external view returns (uint256 shares);

    /**
     * @notice Get total assets managed by this vault (ERC4626-compatible)
     * @return Total assets in base asset (in base asset decimals)
     * @dev Returns the total assets via Manager pass-through function
     */
    function totalAssets() external view returns (uint256);

    /**
     * @notice Preview deposit - calculate shares for given assets
     * @param assets Amount of assets to deposit (in base asset decimals)
     * @return shares Amount of shares to receive (18 decimals)
     * @dev ERC4626-compatible preview function
     */
    function previewDeposit(uint256 assets) external view returns (uint256 shares);

    /**
     * @notice Preview redeem - calculate assets for given shares
     * @param shares Amount of shares to redeem (18 decimals)
     * @return assets Amount of assets to receive (in base asset decimals)
     * @dev ERC4626-compatible preview function
     */
    function previewRedeem(uint256 shares) external view returns (uint256 assets);

    /**
     * @notice Preview withdrawal - calculate shares needed to withdraw given assets
     * @param assets Amount of assets to withdraw (in base asset decimals)
     * @return shares Amount of shares needed (18 decimals)
     * @dev ERC4626-compatible preview function
     */
    function previewWithdraw(uint256 assets) external view returns (uint256 shares);

    /**
     * @notice Preview mint - calculate assets required to mint shares
     * @param shares Amount of shares to mint (18 decimals)
     * @return assets Amount of assets required (in base asset decimals)
     * @dev ERC4626-compatible preview function
     */
    function previewMint(uint256 shares) external view returns (uint256 assets);

    /**
     * @notice Maximum amount of assets that can be deposited (ERC4626-compatible)
     * @param receiver Address that would receive the shares
     * @return maxAssets Maximum amount of assets that can be deposited
     * @dev Returns type(uint256).max unless limited by vault configuration
     */
    function maxDeposit(address receiver) external view returns (uint256 maxAssets);

    /**
     * @notice Maximum amount of shares that can be redeemed (ERC4626-compatible)
     * @param owner Address that owns the shares
     * @return maxShares Maximum amount of shares that can be redeemed
     * @dev Returns owner's balance (unlocked shares)
     */
    function maxRedeem(address owner) external view returns (uint256 maxShares);

    /**
     * @notice Deposit assets into vault and receive shares (ERC4626-compatible)
     * @param assets Amount of assets to deposit (in base asset decimals)
     * @param receiver Address to receive shares
     * @return shares Amount of shares minted (18 decimals)
     * @dev Pass-through to Manager.deposit using vault's base asset
     */
    function deposit(uint256 assets, address receiver) external returns (uint256 shares);

    /**
     * @notice Get CCIP admin address
     * @return admin CCIP admin address
     * @dev Returns the administrator contract address (CCIP admin can be managed through Administrator)
     */
    function getCCIPAdmin() external view returns (address);

    /**
     * @notice Latest Round data from price oracle
     * @return roundId Round ID
     * @return answer Answer
     * @return startedAt Started at
     * @return updatedAt Updated at
     * @return answeredInRound Answered in round
     */
    function latestRoundData() external view returns (uint80 roundId, int256 answer, uint256 startedAt, uint256 updatedAt, uint80 answeredInRound);

    /**
     * @notice getRate for price informaton
     * @return rate Rate for price information
     * @dev Returns the rate for price information in 18 decimals
     */
    function getRate() external view returns (uint256 rate);
}

// SPDX-License-Identifier: GPL-2.0
pragma solidity ^0.8.24;

import {AccessControl} from "../access/AccessControl.sol";
import {IRegistry} from "./interfaces/IRegistry.sol";
import {Administrator} from "../access/Administrator.sol";
import {AddressLib} from "../libraries/AddressLib.sol";
import {Constants} from "../libraries/Constants.sol";
import {Roles} from "../libraries/Roles.sol";
import {Errors} from "../libraries/Errors.sol";

/**
 * @title Registry
 * @author YieldFi Team
 * @notice Central registry for managing vault registration and vault-specific parameters
 * @dev Stores vault registration status, deposit recipients, redemption sources, fee receivers, and fee rates
 * @dev Implements two-step address transfer pattern for depositRecipients and feeReceivers:
 *      - setDepositRecipient/setFeeReceiver sets a pending address
 *      - acceptDepositRecipient/acceptFeeReceiver must be called by the new address to complete the transfer
 *      This prevents accidental or malicious address changes
 */
contract Registry is AccessControl, IRegistry {
    using AddressLib for address;

    // ═══════════════════════════════════════════════════════════════════
    //                          STATE VARIABLES
    // ═══════════════════════════════════════════════════════════════════

    /// @notice Mapping from vault address to registration status
    /// @dev key: vault (address), value: isRegistered (bool)
    mapping(address vault => bool isRegistered) public registered;

    /// @notice Mapping from vault address to deposit recipient address (where deposit funds are sent)
    /// @dev key: vault (address), value: depositRecipient (address)
    mapping(address vault => address depositRecipient) public depositRecipients;

    /// @notice Mapping from vault address to pending deposit recipient address (two-step transfer)
    /// @dev key: vault (address), value: pendingDepositRecipient (address)
    mapping(address vault => address pendingDepositRecipient) public pendingDepositRecipients;

    /// @notice Mapping from vault address to redemption source address (where redemption funds come from)
    /// @dev key: vault (address), value: redemptionSource (address)
    mapping(address vault => address redemptionSource) public redemptionSources;

    /// @notice Mapping from vault address to fee receiver address
    /// @dev key: vault (address), value: feeReceiver (address)
    mapping(address vault => address feeReceiver) public feeReceivers;

    /// @notice Mapping from vault address to pending fee receiver address (two-step transfer)
    /// @dev key: vault (address), value: pendingFeeReceiver (address)
    mapping(address vault => address pendingFeeReceiver) public pendingFeeReceivers;

    /// @notice Mapping from vault address to management fee rate (18 decimals)
    /// @dev key: vault (address), value: managementFee (uint256)
    mapping(address vault => uint256 managementFee) public managementFees;

    /// @notice Mapping from vault address to performance fee rate (18 decimals)
    /// @dev key: vault (address), value: performanceFee (uint256)
    mapping(address vault => uint256 performanceFee) public performanceFees;

    /// @notice Mapping from vault address to curator address
    /// @dev key: vault (address), value: curator (address)
    mapping(address vault => address curator) public curators;

    /// @notice Mapping from vault address to redemption enabled flag
    /// @dev key: vault (address), value: isRedemptionEnabled (bool)
    mapping(address vault => bool isRedemptionEnabled) public isRedemptionEnabled;

    /// @notice Mapping from vault address to base asset address
    /// @dev key: vault (address), value: baseAsset (address)
    mapping(address vault => address baseAsset) public baseAssets;

    /// @notice Mapping from vault address to pause status
    /// @dev key: vault (address), value: isPaused (bool)
    mapping(address vault => bool isPaused) public vaultPaused;

    /// @notice Mapping from vault => asset => asset-level fee configuration
    /// @dev key: vault (address), nested key: asset (address), value: feeConfig (AssetFeeConfig)
    mapping(address vault => mapping(address asset => AssetFeeConfig feeConfig))
        public assetFeeConfigs;

    /// @notice Asset-level fee configuration structure
    struct AssetFeeConfig {
        uint256 depositFee;
        uint256 redemptionFee;
    }

    /// @notice Mapping from vault address to buffer for management and performance fees
    /// @dev key: vault (address), value: feeBuffer (FeeBuffer)
    mapping(address vault => FeeBuffer feeBuffer) public feeBuffers;

    /// @notice Buffer for management and performance fees
    struct FeeBuffer {
        uint256 managementFeeBuffer;
        uint256 performanceFeeBuffer;
    }

    /**
     * @dev Storage gap for upgradeable contracts
     * CRITICAL: Update gap when adding/removing state variables
     * Current usage:
     * - registered: 1 slot (mapping)
     * - depositRecipients: 1 slot (mapping)
     * - pendingDepositRecipients: 1 slot (mapping)
     * - redemptionSources: 1 slot (mapping)
     * - feeReceivers: 1 slot (mapping)
     * - pendingFeeReceivers: 1 slot (mapping)
     * - managementFees: 1 slot (mapping)
     * - performanceFees: 1 slot (mapping)
     * - curators: 1 slot (mapping)
     * - isRedemptionEnabled: 1 slot (mapping)
     * - baseAssets: 1 slot (mapping)
     * - vaultPaused: 1 slot (mapping)
     * - assetFeeConfigs: 1 slot (mapping)
     * - AccessControl parent: ~1 slot (administrator)
     * - Gap: 72 - 14 = 58 slots remaining
     * Note: _gap follows OpenZeppelin's standard pattern for upgradeable contracts
     */
    uint256[58] private _gap;

    // ═══════════════════════════════════════════════════════════════════
    //                            MODIFIERS
    // ═══════════════════════════════════════════════════════════════════

    // (No modifiers currently)

    // ═══════════════════════════════════════════════════════════════════
    //                         INITIALIZATION
    // ═══════════════════════════════════════════════════════════════════

    /**
     * @notice Initialize the Registry contract
     * @param administrator_ Address of the Administrator contract
     */
    function initialize(address administrator_) external initializer {
        administrator_.requireNonZeroContract();
        __AccessControl_init(administrator_);
        emit AdministratorSet(address(0), administrator_);
    }

    // ═══════════════════════════════════════════════════════════════════
    //                      INTERNAL VIEW FUNCTIONS
    // ═══════════════════════════════════════════════════════════════════

    // (No internal view functions currently)

    // ═══════════════════════════════════════════════════════════════════
    //                      EXTERNAL VIEW FUNCTIONS
    // ═══════════════════════════════════════════════════════════════════

    /**
     * @notice Check if a vault is registered
     * @param vault Vault address to check
     * @return isRegistered True if vault is registered
     */
    function isVaultRegistered(
        address vault
    ) external view override returns (bool isRegistered) {
        isRegistered = registered[vault];
    }

    /**
     * @notice Get deposit recipient for a vault
     * @param vault Vault address
     * @return depositRecipient Deposit recipient address
     */
    function getDepositRecipient(
        address vault
    ) external view override returns (address depositRecipient) {
        depositRecipient = depositRecipients[vault];
    }

    /**
     * @notice Get redemption source for a vault
     * @param vault Vault address
     * @return redemptionSource Redemption source address
     */
    function getRedemptionSource(
        address vault
    ) external view override returns (address redemptionSource) {
        redemptionSource = redemptionSources[vault];
    }

    /**
     * @notice Get fee receiver for a vault
     * @param vault Vault address
     * @return feeReceiver Fee receiver address
     */
    function getFeeReceiver(
        address vault
    ) external view override returns (address feeReceiver) {
        feeReceiver = feeReceivers[vault];
    }

    /**
     * @notice Get management fee rate for a vault
     * @param vault Vault address
     * @return managementFee Management fee rate (18 decimals)
     */
    function getManagementFee(
        address vault
    ) external view override returns (uint256 managementFee) {
        managementFee = managementFees[vault];
    }

    /**
     * @notice Get performance fee rate for a vault
     * @param vault Vault address
     * @return performanceFee Performance fee rate (18 decimals)
     */
    function getPerformanceFee(
        address vault
    ) external view override returns (uint256 performanceFee) {
        performanceFee = performanceFees[vault];
    }

    /**
     * @notice Get curator for a vault
     * @param vault Vault address
     * @return curator Curator address
     */
    function getCurator(
        address vault
    ) external view override returns (address curator) {
        curator = curators[vault];
    }

    /**
     * @notice Internal function to check vault-specific curator
     * @dev Can be called by other contracts to check curator access
     * @param vault Vault address to check curator for
     * @param caller Address to check (typically msg.sender from calling contract)
     */
    function onlyCuratorForVault(
        address vault,
        address caller
    ) public view {
        vault.requireNonZeroContract();
        address curator = curators[vault];
        if (caller != curator) {
            revert Errors.Unauthorized(caller, bytes32(0));
        }
    }

    // ═══════════════════════════════════════════════════════════════════
    //                      INTERNAL WRITE FUNCTIONS
    // ═══════════════════════════════════════════════════════════════════

    /**
     * @notice Internal function to validate vault is registered
     * @param vault Vault address to validate
     */
    function _requireVaultRegistered(address vault) internal view {
        vault.requireNonZeroContract();
        if (!registered[vault]) revert Errors.VaultNotRegistered(vault);
    }

    // ═══════════════════════════════════════════════════════════════════
    //                      EXTERNAL WRITE FUNCTIONS
    // ═══════════════════════════════════════════════════════════════════

    /**
     * @notice Register a vault with its configuration
     * @param vault Vault address to register
     * @param config Vault configuration parameters
     */
    function registerVault(
        address vault,
        IRegistry.VaultConfig calldata config
    ) external override onlyOperator {
        vault.requireNonZeroContract();
        config.depositRecipient.requireNonZero();
        config.redemptionSource.requireNonZero();
        config.feeReceiver.requireNonZero();
        config.curator.requireNonZero();
        config.baseAsset.requireNonZero();

        if (config.managementFee > Constants.MAX_MANAGEMENT_FEE) {
            revert Errors.ExcessiveManagementFee(
                config.managementFee,
                Constants.MAX_MANAGEMENT_FEE
            );
        }
        if (config.performanceFee > Constants.MAX_PERFORMANCE_FEE) {
            revert Errors.ExcessivePerformanceFee(
                config.performanceFee,
                Constants.MAX_PERFORMANCE_FEE
            );
        }

        registered[vault] = true;
        pendingDepositRecipients[vault] = address(0); // clear any stale pending deposit recipient
        pendingFeeReceivers[vault] = address(0); // clear any stale pending fee receiver
        depositRecipients[vault] = config.depositRecipient;
        redemptionSources[vault] = config.redemptionSource;
        feeReceivers[vault] = config.feeReceiver;
        curators[vault] = config.curator;
        baseAssets[vault] = config.baseAsset;
        managementFees[vault] = config.managementFee;
        performanceFees[vault] = config.performanceFee;
        isRedemptionEnabled[vault] = true; // Enable redemptions by default

        emit VaultRegistered(
            vault,
            config.depositRecipient,
            config.redemptionSource,
            config.feeReceiver,
            config.curator,
            config.baseAsset,
            config.managementFee,
            config.performanceFee
        );
    }

    /**
     * @notice Unregister a vault
     * @param vault Vault address to unregister
     */
    function unregisterVault(address vault) external override onlyOperator {
        vault.requireNonZeroContract();
        registered[vault] = false;
        pendingDepositRecipients[vault] = address(0); // clear any stale pending deposit recipient
        pendingFeeReceivers[vault] = address(0); // clear any stale pending fee receiver
        emit VaultUnregistered(vault);
    }

    /**
     * @notice Set pending deposit recipient for a vault (two-step transfer)
     * @param vault Vault address
     * @param depositRecipient New deposit recipient address (must accept to complete transfer)
     */
    function setDepositRecipient(
        address vault,
        address depositRecipient
    ) external override onlyOperator {
        _requireVaultRegistered(vault);
        depositRecipient.requireNonZero();

        pendingDepositRecipients[vault] = depositRecipient;
        emit DepositRecipientPending(vault, depositRecipient);
    }

    /**
     * @notice Accept deposit recipient change (two-step transfer)
     * @param vault Vault address
     * @dev Can only be called by the pending deposit recipient address
     */
    function acceptDepositRecipient(address vault) external {
        _requireVaultRegistered(vault);
        address pending = pendingDepositRecipients[vault];
        if (msg.sender != pending) {
            revert Errors.Unauthorized(msg.sender, bytes32(0));
        }

        address oldDepositRecipient = depositRecipients[vault];
        depositRecipients[vault] = pending;
        pendingDepositRecipients[vault] = address(0);

        emit DepositRecipientUpdated(vault, oldDepositRecipient, pending);
    }

    /**
     * @notice Set redemption source for a vault
     * @param vault Vault address
     * @param redemptionSource New redemption source address
     */
    function setRedemptionSource(
        address vault,
        address redemptionSource
    ) external override onlyOperator {
        _requireVaultRegistered(vault);
        redemptionSource.requireNonZero();

        address oldRedemptionSource = redemptionSources[vault];
        redemptionSources[vault] = redemptionSource;
        emit RedemptionSourceUpdated(
            vault,
            oldRedemptionSource,
            redemptionSource
        );
    }

    /**
     * @notice Set pending fee receiver for a vault (two-step transfer)
     * @param vault Vault address
     * @param feeReceiver New fee receiver address (must accept to complete transfer)
     */
    function setFeeReceiver(
        address vault,
        address feeReceiver
    ) external override onlyOperator {
        _requireVaultRegistered(vault);
        feeReceiver.requireNonZero();

        pendingFeeReceivers[vault] = feeReceiver;
        emit FeeReceiverPending(vault, feeReceiver);
    }

    /**
     * @notice Accept fee receiver change (two-step transfer)
     * @param vault Vault address
     * @dev Can only be called by the pending fee receiver address
     */
    function acceptFeeReceiver(address vault) external {
        _requireVaultRegistered(vault);
        address pending = pendingFeeReceivers[vault];
        if (msg.sender != pending) {
            revert Errors.Unauthorized(msg.sender, bytes32(0));
        }

        address oldFeeReceiver = feeReceivers[vault];
        feeReceivers[vault] = pending;
        pendingFeeReceivers[vault] = address(0);

        emit FeeReceiverUpdated(vault, oldFeeReceiver, pending);
    }

    /**
     * @notice Set vault fee rates (management and performance)
     * @param vault Vault address
     * @param managementFee Management fee rate (18 decimals)
     * @param performanceFee Performance fee rate (18 decimals)
     */
    function setVaultFees(
        address vault,
        uint256 managementFee,
        uint256 performanceFee
    ) external override onlyOperator {
        _requireVaultRegistered(vault);

        if (managementFee > Constants.MAX_MANAGEMENT_FEE) {
            revert Errors.ExcessiveManagementFee(
                managementFee,
                Constants.MAX_MANAGEMENT_FEE
            );
        }
        if (performanceFee > Constants.MAX_PERFORMANCE_FEE) {
            revert Errors.ExcessivePerformanceFee(
                performanceFee,
                Constants.MAX_PERFORMANCE_FEE
            );
        }

        managementFees[vault] = managementFee;
        performanceFees[vault] = performanceFee;
        emit VaultFeesConfigured(vault, managementFee, performanceFee);
    }

    /**
     * @notice Set curator for a vault
     * @param vault Vault address
     * @param curator New curator address
     */
    function setCurator(
        address vault,
        address curator
    ) external override onlyOperator {
        _requireVaultRegistered(vault);
        curator.requireNonZero();

        address oldCurator = curators[vault];
        curators[vault] = curator;
        emit CuratorUpdated(vault, oldCurator, curator);
    }

    /**
     * @notice Set redemption enabled status for a vault
     * @param vault Vault address
     * @param enabled True to enable redemptions, false to disable
     */
    function setRedemptionEnabled(
        address vault,
        bool enabled
    ) external override onlyOperator {
        _requireVaultRegistered(vault);

        isRedemptionEnabled[vault] = enabled;
        emit RedemptionEnabled(vault, enabled);
    }

    /**
     * @notice Get base asset for a vault
     * @param vault Vault address
     * @return baseAsset Base asset address
     */
    function getBaseAsset(
        address vault
    ) external view returns (address baseAsset) {
        return baseAssets[vault];
    }

    /**
     * @notice Set base asset for a vault
     * @param vault Vault address
     * @param baseAsset New base asset address
     */
    function setBaseAsset(
        address vault,
        address baseAsset
    ) external override onlyOperator {
        _requireVaultRegistered(vault);
        baseAsset.requireNonZero();

        address oldBaseAsset = baseAssets[vault];
        baseAssets[vault] = baseAsset;
        emit BaseAssetUpdated(vault, oldBaseAsset, baseAsset);
    }

    /**
     * @notice Pause a vault (curator or operator can pause)
     * @param vault Vault address
     */
    function pauseVault(address vault) external override {
        _requireVaultRegistered(vault);

        // Check if caller is curator for this vault OR has OPERATOR_ROLE
        address curator = curators[vault];
        bool isCurator = msg.sender == curator;
        bool isOperator = _hasRole(Roles.OPERATOR_ROLE, msg.sender);

        if (!isCurator && !isOperator) {
            revert Errors.Unauthorized(msg.sender, Roles.OPERATOR_ROLE);
        }

        if (vaultPaused[vault]) {
            revert Errors.VaultAlreadyPaused(vault);
        }

        vaultPaused[vault] = true;
        emit VaultPaused(vault, msg.sender);
    }

    /**
     * @notice Unpause a vault (only operator can unpause)
     * @param vault Vault address
     */
    function unpauseVault(address vault) external override onlyOperator {
        _requireVaultRegistered(vault);

        if (!vaultPaused[vault]) {
            revert Errors.VaultNotPaused(vault);
        }

        vaultPaused[vault] = false;
        emit VaultUnpaused(vault, msg.sender);
    }

    /**
     * @notice Check if a vault is paused (checks both vault-level and global pause)
     * @param vault Vault address
     * @return paused True if vault is paused or global pause is active
     */
    function isVaultPaused(address vault) external view override returns (bool paused) {
        // Check global pause first
        if (administrator != address(0)) {
            if (Administrator(administrator).isGloballyPaused()) {
                return true;
            }
        }
        // Check vault-level pause
        return vaultPaused[vault];
    }

    /**
     * @notice Get asset-level fee configuration for a vault and asset
     * @param vault Vault address
     * @param asset Asset address
     * @return config Asset fee configuration (deposit and redemption fees)
     */
    function getAssetFeeConfig(
        address vault,
        address asset
    ) external view returns (AssetFeeConfig memory config) {
        config = assetFeeConfigs[vault][asset];
    }

    /**
     * @notice Configure asset-level fees (deposit and redemption fees)
     * @param vault Vault address
     * @param asset Asset address
     * @param depositFee Deposit fee rate (18 decimals)
     * @param redemptionFee Redemption fee rate (18 decimals)
     */
    function configureAssetFees(
        address vault,
        address asset,
        uint256 depositFee,
        uint256 redemptionFee
    ) external onlyOperator {
        vault.requireNonZeroContract();
        asset.requireNonZero();

        AssetFeeConfig storage config = assetFeeConfigs[vault][asset];
        config.depositFee = depositFee;
        config.redemptionFee = redemptionFee;

        emit AssetFeeConfigUpdated(vault, asset, depositFee, redemptionFee);
    }

    /**
     * @notice Set fee buffers for management and performance fees
     * @param vault Vault address
     * @dev each of the buffer is represented in % which 0.01e18 = 1%
     * @param managementFeeBuffer Management fee buffer (18 decimals)
     * @param performanceFeeBuffer Performance fee buffer (18 decimals)
     */
    function setFeeBuffers(
        address vault,
        uint256 managementFeeBuffer,
        uint256 performanceFeeBuffer
    ) external onlyOperator {
        _requireVaultRegistered(vault);
        feeBuffers[vault] = FeeBuffer({
            managementFeeBuffer: managementFeeBuffer,
            performanceFeeBuffer: performanceFeeBuffer
        });
        emit FeeBuffersSet(vault, managementFeeBuffer, performanceFeeBuffer);
    }

    /**
     * @notice Get fee buffers for management and performance fees
     * @param vault Vault address
     * @return managementFeeBuffer Management fee buffer (18 decimals)
     * @return performanceFeeBuffer Performance fee buffer (18 decimals)
     */
    function getFeeBuffers(address vault) external view override returns (uint256 managementFeeBuffer, uint256 performanceFeeBuffer) {
        return (feeBuffers[vault].managementFeeBuffer, feeBuffers[vault].performanceFeeBuffer);
    }

    /**
     * @notice Add buffer to fee
     * @param fee Fee (18 decimals)
     * @param buffer Buffer (18 decimals)
     * @return feeWithBuffer Fee with buffer (18 decimals)
     */
    function _addBuffer(uint256 fee, uint256 buffer) internal pure returns (uint256) {
        return (fee * (Constants.HUNDRED_PERCENT + buffer)) / Constants.HUNDRED_PERCENT;
    }

    /**
     * @notice Get fees with buffers
     * @param vault Vault address
     * @return managementFeeWithBuffer Management fee with buffer (18 decimals)
     * @return performanceFeeWithBuffer Performance fee with buffer (18 decimals)
     */
    function getFeesWithBuffer(address vault) external view override returns (uint256 managementFeeWithBuffer, uint256 performanceFeeWithBuffer) {

        uint256 managementFeeRate = managementFees[vault];
        uint256 performanceFeeRate = performanceFees[vault];
        FeeBuffer memory feeBuffer = feeBuffers[vault];

        managementFeeWithBuffer = _addBuffer(managementFeeRate, feeBuffer.managementFeeBuffer);
        performanceFeeWithBuffer = _addBuffer(performanceFeeRate, feeBuffer.performanceFeeBuffer);

        return (managementFeeWithBuffer, performanceFeeWithBuffer);
    }
}

