pragma solidity ^0.8.24;

import {AccessControl} from "../access/AccessControl.sol";
import {AddressLib} from "../libraries/AddressLib.sol";
import {AccountingLib} from "../libraries/AccountingLib.sol";
import {MathLib} from "../libraries/MathLib.sol";
import {Errors} from "../libraries/Errors.sol";

/**
 * @title NAV
 * @author YieldFi Team
 * @notice Contract for managing NAV (Net Asset Value) state and calculations per vault
 * @dev Handles NAV updates, High Water Mark tracking, and NAV-based calculations
 * @dev Keeps Vault contract pure ERC20 by moving all NAV logic here
 * @dev Features:
 *      - High Water Mark (HWM) tracking: Records maximum NAV per vault
 *      - Vesting parameters: Manages NAV vesting with start/end NAV and timestamps
 *      - Manager-only access: Only Manager contract can update NAV state
 *      - Per-vault metrics: Each vault has independent NAV metrics
 */
contract NAV is AccessControl {
    using AddressLib for address;
    using AccountingLib for uint256;
    using MathLib for uint256;

    // ═══════════════════════════════════════════════════════════════════
    //                          STATE VARIABLES
    // ═══════════════════════════════════════════════════════════════════

    /// @notice NAV metrics per vault
    struct NavMetrics {
        /// @notice High Water Mark (maximum NAV recorded, 18 decimals)
        uint256 highWaterMark;
        /// @notice Vesting parameters
        VestingParams vesting;
    }

    /// @notice Vesting parameters for NAV
    struct VestingParams {
        /// @notice NAV at the start of vesting (18 decimals)
        uint256 startNav;
        /// @notice NAV at the end of vesting (target NAV, 18 decimals)
        uint256 endNav;
        /// @notice Vesting start timestamp
        uint256 start;
        /// @notice Vesting end timestamp
        uint256 end;
    }

    /// @notice NAV metrics per vault
    /// @dev key: vault (address), value: metrics (NavMetrics)
    mapping(address vault => NavMetrics metrics) public navMetrics;

    /// @notice Manager contract address (authorized to call NAV functions)
    address public manager;

    /**
     * @dev Storage gap for upgradeable contracts
     * CRITICAL: Update gap when adding/removing state variables
     * Current usage:
     * - navMetrics: 1 slot (mapping)
     * - manager: 1 slot
     * - AccessControl parent: ~1 slot (administrator)
     * Total: 3 slots used
     * Gap: 72 - 3 = 69 slots remaining
     * Note: _gap follows OpenZeppelin's standard pattern for upgradeable contracts
     */
    uint256[69] private _gap;

    // ═══════════════════════════════════════════════════════════════════
    //                             EVENTS
    // ═══════════════════════════════════════════════════════════════════

    /// @notice Emitted when NAV is updated
    event NAVUpdated(
        address indexed vault,
        uint256 oldNav,
        uint256 newNav,
        uint256 vestingEndTime
    );

    /// @notice Emitted when High Water Mark is updated
    event HighWaterMarkUpdated(
        address indexed vault,
        uint256 oldHwm,
        uint256 newHwm
    );


    // ═══════════════════════════════════════════════════════════════════
    //                         INITIALIZATION
    // ═══════════════════════════════════════════════════════════════════

    /// @custom:oz-upgrades-unsafe-allow constructor
    constructor() {
        _disableInitializers();
    }

    /**
     * @notice Initialize the NAV contract
     * @param administrator_ Administrator contract address
     * @param manager_ Manager contract address
     */
    function initialize(
        address administrator_,
        address manager_
    ) external initializer {
        administrator_.requireNonZeroContract();
        manager_.requireNonZeroContract();
        __AccessControl_init(administrator_);
        manager = manager_;
    }

    /**
     * @notice Set Manager contract address
     * @param manager_ New Manager contract address
     */
    function setManager(address manager_) external onlyOperator {
        manager_.requireNonZeroContract();
        manager = manager_;
    }

    // ═══════════════════════════════════════════════════════════════════
    //                            MODIFIERS
    // ═══════════════════════════════════════════════════════════════════

    /// @notice Modifier to restrict function access to Manager contract only
    modifier onlyManager() {
        _onlyManager();
        _;
    }

    /// @notice Internal function to check Manager access
    function _onlyManager() internal view {
        if (msg.sender != manager) revert Errors.UnauthorizedCaller();
    }

    // ═══════════════════════════════════════════════════════════════════
    //                      EXTERNAL VIEW FUNCTIONS
    // ═══════════════════════════════════════════════════════════════════

    /**
     * @notice Get NAV for a vault (returns vested/vesting NAV)
     * @param vault Vault address
     * @return navValue Vested or vesting NAV (18 decimals)
     * @dev If vesting is active, returns linearly interpolated NAV between start and target NAV
     * @dev If vesting has ended, returns the full target NAV
     */
    function getNav(address vault) public view returns (uint256 navValue) {
        VestingParams memory vesting = navMetrics[vault].vesting;

        // If no vesting or vesting has ended, return end NAV (target NAV)
        if (block.timestamp >= vesting.end) {
            return vesting.endNav;
        }

        // If vesting hasn't started yet, return start NAV
        if (block.timestamp < vesting.start) {
            return vesting.startNav;
        }

        // Vesting is active - calculate vested NAV using linear interpolation
        // vestedNav = startNav + (endNav - startNav) * (timeElapsed / vestingDuration)
        uint256 timeElapsed = MathLib.safeSub(block.timestamp, vesting.start);
        uint256 vestingDuration = MathLib.safeSub(vesting.end, vesting.start);

        if (vestingDuration == 0) { // safety check for division by zero 
            return vesting.endNav;
        }

        // Calculate vested portion
        uint256 navIncrease = vesting.endNav > vesting.startNav 
            ? MathLib.safeSub(vesting.endNav, vesting.startNav)
            : 0;
        uint256 vestedIncrease = MathLib.safeDiv(
            MathLib.safeMul(navIncrease, timeElapsed),
            vestingDuration
        );

        return MathLib.safeAdd(vesting.startNav, vestedIncrease);
    }

    /**
     * @notice Get stored NAV for a vault (target NAV from vesting parameters)
     * @param vault Vault address
     * @return navValue Target NAV (endNav from vesting params, 18 decimals)
     * @dev Returns the target NAV (endNav), not the vested/vesting NAV from getNav()
     */
    function getStoredNav(address vault) external view returns (uint256 navValue) {
        return navMetrics[vault].vesting.endNav;
    }

    /**
     * @notice Get High Water Mark for a vault
     * @param vault Vault address
     * @return hwm High Water Mark (18 decimals)
     */
    function getHighWaterMark(
        address vault
    ) external view returns (uint256 hwm) {
        return navMetrics[vault].highWaterMark;
    }

    /**
     * @notice Calculate TVL (Total Value Locked) - computed value
     * @param vault Vault address
     * @param totalShares Total share supply (18 decimals)
     * @return tvl Computed TVL (18 decimals)
     */
    function calculateTvl(
        address vault,
        uint256 totalShares
    ) external view returns (uint256 tvl) {
        uint256 currentNav = getNav(vault);
        if (currentNav == 0) {
            return 0;
        }
        return AccountingLib.calculateTvl(totalShares, currentNav);
    }

    // ═══════════════════════════════════════════════════════════════════
    //                      EXTERNAL WRITE FUNCTIONS
    // ═══════════════════════════════════════════════════════════════════

    /**
     * @notice Initialize NAV for a vault (first deposit)
     * @param vault Vault address
     * @param nav Initial NAV value (18 decimals)
     * @dev Sets NAV to the provided value and initializes HWM
     */
    function initializeNav(
        address vault,
        uint256 nav
    ) external onlyOperator {
        vault.requireNonZeroContract();
        if (nav == 0) revert Errors.ZeroAmount();
        NavMetrics storage metrics = navMetrics[vault];

        // Prevent accidental re-initialization: check both endNav and highWaterMark
        if (metrics.vesting.endNav != 0 || metrics.highWaterMark != 0) {
            revert Errors.NavAlreadyInitialized(vault);
        }

        metrics.highWaterMark = nav;
        // Initialize vesting params with provided NAV (no vesting initially)
        metrics.vesting = VestingParams({
            startNav: nav,
            endNav: nav,
            start: block.timestamp,
            end: block.timestamp
        });

        emit NAVUpdated(vault, 0, nav, block.timestamp);
        emit HighWaterMarkUpdated(vault, 0, nav);
    }

    /**
     * @notice Update NAV for a vault
     * @param vault Vault address
     * @param newNav New NAV value (target NAV, 18 decimals)
     * @param endTime Vesting end timestamp
     * @dev Sets vesting parameters: startNav = current vested NAV, endNav = newNav, start = now, end = endTime
     * @dev Updates High Water Mark based on endNav
     */
    function updateNav(
        address vault,
        uint256 newNav,
        uint256 endTime
    ) external onlyManager {
        vault.requireNonZeroContract();
        if (newNav == 0) revert Errors.ZeroAmount();

        NavMetrics storage metrics = navMetrics[vault];

        // Get current stored NAV (endNav) as startNav for vesting
        uint256 currentVestedNav = getNav(vault);

        // block time
        uint256 currentBlockTime = block.timestamp;

        // force set the endtime to block.timestamp if new nav is negative
        uint256 vestingEndTime = newNav <= currentVestedNav ? currentBlockTime : endTime;

        // Set vesting parameters: startNav = current stored NAV (endNav), endNav = newNav, start = now, end = vestingEndTime
        metrics.vesting = VestingParams({
            startNav: currentVestedNav,
            endNav: newNav,
            start: currentBlockTime,
            end: vestingEndTime
        });

        // Update High Water Mark based on endNav (target NAV)
        if (newNav > metrics.highWaterMark) {
            emit HighWaterMarkUpdated(vault, metrics.highWaterMark, newNav);
            metrics.highWaterMark = newNav;
        }

        emit NAVUpdated(vault, currentVestedNav, newNav, vestingEndTime);
    }

    /**
     * @notice Get vesting parameters for a vault
     * @param vault Vault address
     * @return startNav NAV at the start of vesting
     * @return endNav NAV at the end of vesting
     * @return start Vesting start timestamp
     * @return end Vesting end timestamp
     */
    function getVestingParams(
        address vault
    ) external view returns (
        uint256 startNav,
        uint256 endNav,
        uint256 start,
        uint256 end
    ) {
        VestingParams storage vesting = navMetrics[vault].vesting;
        (startNav, endNav, start, end) = (vesting.startNav, vesting.endNav, vesting.start, vesting.end);
    }

    /**
     * @notice Set High Water Mark for a vault (EMERGENCY ONLY)
     * @param vault Vault address
     * @param newHwm New High Water Mark value (18 decimals)
     * @dev EMERGENCY FUNCTION: Used only in emergency situations to manually set the high watermark NAV.
     * Generally, the high watermark is automatically updated when NAV increases and should not be manually set.
     * This function allows emergency operators to correct the high watermark in case of critical issues.
     * @dev Emits HighWaterMarkUpdated event
     */
    function setHwNav(
        address vault,
        uint256 newHwm
    ) external onlyEmergencyOperator {
        vault.requireNonZeroContract();
        if (newHwm == 0) revert Errors.ZeroAmount();

        NavMetrics storage metrics = navMetrics[vault];
        uint256 oldHwm = metrics.highWaterMark;
        metrics.highWaterMark = newHwm;

        emit HighWaterMarkUpdated(vault, oldHwm, newHwm);
    }
}

