pragma solidity ^0.8.24;

/**
 * @title IPriceOracle
 * @author YieldFi Team
 * @notice Interface for price oracle system that provides asset prices for collateral valuation
 * @dev Supports single and dual oracle modes with staleness checks and deviation validation
 */
interface IPriceOracle {
    // ═══════════════════════════════════════════════════════════════════
    //                             ENUMS
    // ═══════════════════════════════════════════════════════════════════

    /**
     * @notice Oracle mode configuration
     */
    enum OracleMode {
        Single, // Single oracle source
        Dual // Dual oracle consensus
    }

    /**
     * @notice Asset type for price adjustment
     */
    enum AssetType {
        YieldBearing, // Yield-bearing assets (LSTs, etc.)
        NonYieldBearing // Non-yield-bearing assets (stablecoins, wrapped BTC)
    }

    // ═══════════════════════════════════════════════════════════════════
    //                             STRUCTS
    // ═══════════════════════════════════════════════════════════════════

    /**
     * @notice Price data structure
     * @param price Price value (18 decimals)
     * @param timestamp Last update timestamp
     * @param isValid True if price is valid and fresh
     */
    struct PriceData {
        uint256 price;
        uint256 timestamp;
        bool isValid;
    }

    /**
     * @notice Oracle configuration for an asset
     * @param mode Oracle mode (Single or Dual)
     * @param primaryOracle Primary oracle address
     * @param secondaryOracle Secondary oracle address (for dual mode)
     * @param assetType Asset type for price adjustment
     * @param maxDeviation Maximum price deviation between oracles (18 decimals, e.g., 5e16 = 5%)
     * @param maxStaleness Maximum staleness period in seconds
     * @param minPrice Minimum deposit price (18 decimals, relative to base asset)
     */
    struct OracleConfig {
        OracleMode mode;
        address primaryOracle;
        address secondaryOracle; // address(0) for single mode
        AssetType assetType;
        uint256 maxDeviation; // 18 decimals
        uint256 maxStaleness; // seconds
        uint256 minPrice; // 18 decimals, minimum deposit price relative to base asset
    }

    // ═══════════════════════════════════════════════════════════════════
    //                             EVENTS
    // ═══════════════════════════════════════════════════════════════════

    /// @notice Emitted when price is updated
    event PriceUpdated(address indexed asset, uint256 price, uint256 timestamp);

    /// @notice Emitted when oracle configuration is updated
    event OracleConfigUpdated(address indexed asset, OracleMode mode, address primaryOracle, address secondaryOracle);

    // ═══════════════════════════════════════════════════════ ════════════
    //                         VIEW FUNCTIONS
    // ═══════════════════════════════════════════════════════════════════

    /**
     * @notice Get price for an asset (with validation)
     * @param asset Asset address
     * @return price Price in 18 decimals
     * @return isValid True if price is valid and fresh
     */
    function getPrice(address asset) external view returns (uint256 price, bool isValid);

    /**
     * @notice Get deposit-adjusted price for an asset in base asset terms
     * @dev Returns the asset price in base asset terms (18 decimals ratio) for reuse
     *      Price represents: assetOraclePrice / baseAssetPrice (in 18 decimals)
     *      Can be multiplied directly with asset amount to get deposit value in base asset
     *      Applies asset-specific adjustments (e.g., non-yield-bearing assets capped at 1.0)
     * @param asset Asset address
     * @param baseAsset Base asset address
     * @return price Asset price in base asset terms (18 decimals ratio)
     * @return isValid True if price is valid
     */
    function getDepositPrice(address asset, address baseAsset) external view returns (uint256 price, bool isValid);

    /**
     * @notice Get price data from primary oracle
     * @param asset Asset address
     * @return data Price data structure
     */
    function getPrimaryPrice(address asset) external view returns (PriceData memory data);

    /**
     * @notice Get price data from secondary oracle (if configured)
     * @param asset Asset address
     * @return data Price data structure (invalid if not configured)
     */
    function getSecondaryPrice(address asset) external view returns (PriceData memory data);

    /**
     * @notice Check if price data is fresh
     * @param asset Asset address
     * @return isFresh True if price is within staleness threshold
     */
    function isPriceFresh(address asset) external view returns (bool isFresh);

    /**
     * @notice Get oracle configuration for an asset
     * @param asset Asset address
     * @return config Oracle configuration
     */
    function getOracleConfig(address asset) external view returns (OracleConfig memory config);

    // ═══════════════════════════════════════════════════════════════════
    //                        ADMIN FUNCTIONS
    // ═══════════════════════════════════════════════════════════════════

    /**
     * @notice Set oracle configuration for an asset
     * @param asset Asset address
     * @param config Oracle configuration
     */
    function setOracleConfig(address asset, OracleConfig calldata config) external;

}

