pragma solidity ^0.8.24;

/**
 * @title IFeatureRegistry
 * @author YieldFi Team
 * @notice Interface for feature registry managing vault features
 * @dev Central registry for enabling/disabling features per vault
 */
interface IFeatureRegistry {
    // ═══════════════════════════════════════════════════════════════════
    //                             EVENTS
    // ═══════════════════════════════════════════════════════════════════

    /// @notice Emitted when a feature is registered
    event FeatureRegistered(bytes32 indexed featureId, address indexed featureContract, string name, uint256 version);

    /// @notice Emitted when a feature is enabled for a vault
    event FeatureEnabled(address indexed vault, bytes32 indexed featureId, address indexed featureContract);

    /// @notice Emitted when a feature is disabled for a vault
    event FeatureDisabled(address indexed vault, bytes32 indexed featureId);

    /// @notice Emitted when a feature contract is updated
    event FeatureContractUpdated(bytes32 indexed featureId, address indexed oldContract, address indexed newContract);

    // ═══════════════════════════════════════════════════════════════════
    //                         VIEW FUNCTIONS
    // ═══════════════════════════════════════════════════════════════════

    /**
     * @notice Check if a feature is enabled for a vault
     * @param vault Address of the vault
     * @param featureId Feature identifier
     * @return enabled True if feature is enabled
     */
    function isFeatureEnabled(address vault, bytes32 featureId) external view returns (bool enabled);

    /**
     * @notice Get the contract address for a feature
     * @param featureId Feature identifier
     * @return contractAddress Address of the feature contract (reverts if feature not registered)
     */
    function getFeatureContract(bytes32 featureId) external view returns (address contractAddress);

