pragma solidity ^0.8.24;

import {Constants} from "./Constants.sol";
import {MathLib} from "./MathLib.sol";
import {Errors} from "./Errors.sol";

/**
 * @title AccountingLib
 * @author YieldFi Team
 * @notice Mathematical calculations for vault accounting based on NAV model
 * @dev Implements precision-safe arithmetic for share/asset calculations, fees, and NAV
 *      Based on YieldFi mathematical model: NAV = Net Balance / Total Shares
 */
library AccountingLib {

    // ═══════════════════════════════════════════════════════════════════
    //                        SHARE CALCULATIONS
    // ═══════════════════════════════════════════════════════════════════

    /**
     * @notice Calculate shares to mint for a given deposit value
     * @dev Based on mathematical model: Shares = Value / NAV
     *      Both Value and NAV are 18 decimals. Result is 18 decimals.
     *      Uses MathLib.divPrecision for safe division with 18-decimal precision
     * @param valueInBase Value of deposit in Base Asset (18 decimals)
     * @param nav Current NAV (18 decimals)
     * @return shares Amount of shares to mint (18 decimals)
     */
    function calculateSharesToMint(
        uint256 valueInBase,
        uint256 nav
    ) internal pure returns (uint256 shares) {
        if (nav == 0) revert Errors.ZeroNAV();
        if (valueInBase == 0) return 0;

        // Shares = Value / NAV using MathLib for safe division
        shares = MathLib.divPrecision(valueInBase, nav);
    }

    /**
     * @notice Calculate assets to redeem for a given share amount
     * @dev Based on mathematical model: Assets = Shares * NAV
     *      Uses MathLib.mulDiv18 for safe multiplication of 18-decimal numbers
     * @param shares Amount of shares to burn (18 decimals)
     * @param nav Current NAV (18 decimals)
     * @return assets Value in Base Asset (18 decimals)
     */
    function calculateAssetsToRedeem(
        uint256 shares,
        uint256 nav
    ) internal pure returns (uint256 assets) {
        if (shares == 0) return 0;

        // Assets = Shares * NAV using MathLib for safe multiplication
        assets = MathLib.mulDiv18(shares, nav);
    }


    /**
     * @notice Calculate total TVL (Total Value Locked) from shares and NAV
     * @dev Based on mathematical model: TVL = Total Shares × NAV (computed, not stored)
     *      Uses MathLib.mulDiv18 for safe multiplication of 18-decimal numbers
     * @param totalShares Total share supply (18 decimals)
     * @param nav Current NAV (18 decimals)
     * @return tvl Total Value Locked (18 decimals)
     */
    function calculateTvl(
        uint256 totalShares,
        uint256 nav
    ) internal pure returns (uint256 tvl) {
        // TVL = Total Shares × NAV using MathLib for safe multiplication
        tvl = MathLib.mulDiv18(totalShares, nav);
    }

    // ═══════════════════════════════════════════════════════════════════
    //                          FEE CALCULATIONS
    // ═══════════════════════════════════════════════════════════════════

    /**
     * @notice Calculate deposit or redemption fee on shares
     * @dev Applies fee to shares being minted or redeemed
     * @param shares Shares being minted or redeemed (18 decimals)
     * @param feeRate Fee rate (18 decimals, e.g. 1e16 = 1%, 5e15 = 0.5%)
     * @return netShares Shares after fee deduction (18 decimals)
     * @return feeShares Fee shares to collect (18 decimals)
     */
    function calculateFee(
        uint256 shares,
        uint256 feeRate
    ) internal pure returns (uint256 netShares, uint256 feeShares) {
        if (shares == 0) return (0, 0);
        if (feeRate == 0) return (shares, 0);
        if (feeRate >= Constants.PRECISION) revert Errors.ArithmeticOverflow();

        // Calculate fee shares using MathLib for safe percentage calculation
        feeShares = MathLib.percentageOf(shares, feeRate);
        // Calculate net shares using MathLib for safe subtraction
        netShares = MathLib.safeSub(shares, feeShares);
    }
}

