pragma solidity ^0.8.24;

import {Constants} from "./Constants.sol";
import {Errors} from "./Errors.sol";

/**
 * @title MathLib
 * @author YieldFi Team
 * @notice Safe arithmetic operations and mathematical utilities
 * @dev Provides protocol-favorable rounding and overflow-safe operations
 */
library MathLib {

    // ═══════════════════════════════════════════════════════════════════
    //                         SAFE ARITHMETIC
    // ═══════════════════════════════════════════════════════════════════

    /**
     * @notice Safe addition with overflow protection
     * @param a First addend
     * @param b Second addend
     * @return result Sum of a and b
     */
    function safeAdd(
        uint256 a,
        uint256 b
    ) internal pure returns (uint256 result) {
        unchecked {
            result = a + b;
            if (result < a) revert Errors.ArithmeticOverflow();
        }
    }

    /**
     * @notice Safe subtraction with underflow protection
     * @param a Minuend
     * @param b Subtrahend
     * @return result Difference of a and b
     */
    function safeSub(
        uint256 a,
        uint256 b
    ) internal pure returns (uint256 result) {
        if (b > a) revert Errors.ArithmeticUnderflow();
        unchecked {
            result = a - b;
        }
    }

    /**
     * @notice Safe multiplication with overflow protection
     * @param a First factor
     * @param b Second factor
     * @return result Product of a and b
     */
    function safeMul(
        uint256 a,
        uint256 b
    ) internal pure returns (uint256 result) {
        if (a == 0) return 0;

        unchecked {
            result = a * b;
            if (result / a != b) revert Errors.ArithmeticOverflow();
        }
    }

    /**
     * @notice Safe division with zero protection
     * @param a Dividend
     * @param b Divisor
     * @return result Quotient of a and b
     */
    function safeDiv(
        uint256 a,
        uint256 b
    ) internal pure returns (uint256 result) {
        if (b == 0) revert Errors.DivisionByZero();
        result = a / b;
    }

    // ═══════════════════════════════════════════════════════════════════
    //                      PERCENTAGE CALCULATIONS
    // ═══════════════════════════════════════════════════════════════════

    /**
     * @notice Calculate percentage of a value (protocol-favorable rounding)
     * @dev Rounds DOWN to favor the protocol over users
     * @param value Base value
     * @param percentage Percentage rate (18 decimals, e.g., 5e16 = 5%)
     * @return result Percentage of value (rounded down)
     */
    function percentageOf(
        uint256 value,
        uint256 percentage
    ) internal pure returns (uint256 result) {
        if (value == 0 || percentage == 0) return 0;

        // Round DOWN for protocol-favorable calculation
        result = (value * percentage) / Constants.PRECISION;
    }


    // ═══════════════════════════════════════════════════════════════════
    //                        PRECISION MATH
    // ═══════════════════════════════════════════════════════════════════

    /**
     * @notice Multiply two 18-decimal fixed-point numbers
     * @param a First number (18 decimals)
     * @param b Second number (18 decimals)
     * @return result Product (18 decimals)
     */
    function mulDiv18(
        uint256 a,
        uint256 b
    ) internal pure returns (uint256 result) {
        result = (a * b) / Constants.PRECISION;
    }

    /**
     * @notice Divide with 18-decimal precision
     * @param a Dividend
     * @param b Divisor
     * @return result Quotient (18 decimals)
     */
    function divPrecision(
        uint256 a,
        uint256 b
    ) internal pure returns (uint256 result) {
        if (b == 0) revert Errors.DivisionByZero();
        result = (a * Constants.PRECISION) / b;
    }

    /**
     * @notice Scale a value from one decimal precision to another
     * @param value Value to scale
     * @param fromDecimals Current decimal precision
     * @param toDecimals Target decimal precision
     * @return result Scaled value
     */
    function scaleDecimals(
        uint256 value,
        uint8 fromDecimals,
        uint8 toDecimals
    ) internal pure returns (uint256 result) {
        if (fromDecimals == toDecimals) {
            return value;
        } else if (fromDecimals < toDecimals) {
            // Scale up
            uint8 scaleFactor = toDecimals - fromDecimals;
            result = value * (10 ** scaleFactor);
        } else {
            // Scale down
            uint8 scaleFactor = fromDecimals - toDecimals;
            result = value / (10 ** scaleFactor);
        }
    }


    // ═══════════════════════════════════════════════════════════════════
    //                       COMPARISON FUNCTIONS
    // ═══════════════════════════════════════════════════════════════════

    /**
     * @notice Calculate absolute deviation percentage between two values
     * @dev Returns the percentage deviation relative to the minimum value
     * @param value1 First value
     * @param value2 Second value
     * @return deviation Deviation percentage (18 decimals, e.g., 5e16 = 5%)
     * @dev Returns 100% (HUNDRED_PERCENT) if either value is zero
     */
    function absDeviation(
        uint256 value1,
        uint256 value2
    ) internal pure returns (uint256 deviation) {
        if (value1 == 0 || value2 == 0) {
            return Constants.HUNDRED_PERCENT; // 100% deviation if either is zero
        }

        uint256 minValue = value1 < value2 ? value1 : value2;
        uint256 diff = value1 > value2 ? value1 - value2 : value2 - value1;
        // Calculate percentage: (diff * PRECISION) / minValue
        deviation = (diff * Constants.PRECISION) / minValue;
    }

}

