pragma solidity ^0.8.24;

import {Errors} from "./Errors.sol";

/**
 * @title AddressLib
 * @author YieldFi Team
 * @notice Library for address validation utilities
 * @dev Provides reusable functions for zero address and contract checks
 */
library AddressLib {

    // ═══════════════════════════════════════════════════════════════════
    //                        VALIDATION FUNCTIONS
    // ═══════════════════════════════════════════════════════════════════

    /**
     * @notice Validates that an address is not zero
     * @dev Reverts with ZeroAddress error if address is zero
     * @param account Address to validate
     */
    function requireNonZero(address account) internal pure {
        if (account == address(0)) revert Errors.ZeroAddress();
    }

    /**
     * @notice Validates that an address is not zero and contains contract code
     * @dev Combines requireNonZero and contract code checks
     * @param account Address to validate
     */
    function requireNonZeroContract(address account) internal view {
        requireNonZero(account);
        uint256 size;
        // solhint-disable-next-line no-inline-assembly
        assembly {
            size := extcodesize(account)
        }
        if (size == 0) revert Errors.NotContract(account);
    }

    /**
     * @notice Validates multiple addresses are not zero
     * @dev Gas-efficient batch validation
     * @param accounts Array of addresses to validate
     */
    function requireNonZeroBatch(address[] memory accounts) internal pure {
        uint256 length = accounts.length;
        for (uint256 i; i < length; ++i) {
            requireNonZero(accounts[i]);
        }
    }

}

