sourceSemantics.vaultDeposit:
function deposit(
        uint256 assets,
        address receiver
    ) external returns (uint256 shares) {
        IManager managerContract = IManager(manager);
        address baseAsset = managerContract.getVaultAsset(address(this));

        // Transfer assets to the vault from the sender
        IERC20(baseAsset).safeTransferFrom(msg.sender, address(this), assets);

        // receiver blacklisting is chcecked in the manager contract hence only msg.sender is checked
        if (isBlacklisted(msg.sender)) {
            revert Errors.AddressBlacklisted(msg.sender);
        }

        managerContract.validateGreenlist(address(this), msg.sender, receiver);

        // Calculate minimum shares expected (use 0 for no slippage protection in ERC4626 interface)
        // Since this is for base asset, we don't need to worry about slippage protection
        // No oracles are called in this case.
        uint256 minShares = 0;

        // Deposit assets into the vault (manager already has infinite allowance)
        return
            managerContract.deposit(
                address(this),
                baseAsset,
                assets,
                receiver,
                minShares,
                bytes32(0)
            );
    }

managerUserActions.deposit:
function deposit(
        address vault,
        address asset,
        uint256 amount,
        address receiver,
        uint256 minShares,
        bytes32 referralCode
    ) external override whenNotPaused nonReentrant returns (uint256 shares) {
        // Check vault-level pause
        if (contracts.registry.vaultPaused(vault)) {
            revert Errors.VaultPaused(vault);
        }

        // Validate deposit inputs
        _validateDeposit(vault, asset, amount, receiver);

        // Get current NAV (must be initialized before deposit)
        uint256 currentNav = _getAndValidateNav(vault);

        // Calculate total shares to mint from asset (handles base asset, price, value, and shares)
        (uint256 totalSharesToMint, uint256 depositValueInBase) = _calculateDepositSharesFromAsset(
            vault,
            asset,
            amount,
            currentNav
        );

        // Calculate deposit fee: Fee_asset = m × df_f
        (uint256 netShares, uint256 feeShares) = _calculateFees(
            vault,
            asset,
            totalSharesToMint,
            false // isRedemption = false
        );

        if (netShares < minShares) { // Slippage protection
            revert Errors.InsufficientShares(netShares, minShares);
        }

        // Validate deposit limits (before minting shares)
        // Note: validateDeposit calculates from current vault balance/supply
        // The new shares will be minted after validation, so we validate against current state + new deposit
        _validateDepositLimits(vault, receiver, depositValueInBase);

        // Execute deposit: transfer assets, mint shares
        _executeDeposit(
            vault,
            asset,
            amount,
            netShares,
            feeShares,
            receiver,
            referralCode
        );

        return netShares;
    }

managerUserActions.requestRedemption:
function requestRedemption(
        address vault,
        uint256 shares,
        address owner,
        address receiver,
        bytes32 referralCode
    ) external whenNotPaused nonReentrant {
        // Check vault-level pause
        if (contracts.registry.vaultPaused(vault)) {
            revert Errors.VaultPaused(vault);
        }

        // Validate redemption inputs
        _validateRedeem(vault, shares, owner, receiver);

        // Get current NAV (validated to ensure vault is initialized) 
        uint256 currentNav = _getAndValidateNav(vault);

        // Calculate redemption fees, charge fees, and lock net shares
        uint256 netShares = _chargeRedemptionFeesAndLockShares(vault, owner, shares);

        // Create queue entry (lockedShares is netShares after fees)
        RedemptionQueueEntry memory entry = RedemptionQueueEntry({
            owner: owner,
            receiver: receiver,
            lockedShares: netShares,
            navAtRequest: currentNav,
            timestamp: block.timestamp
        });

        // Add to queue
        uint256 queueIndex = nextQueueIndex[vault];
        redemptionQueues[vault][queueIndex] = entry;
        nextQueueIndex[vault] = MathLib.safeAdd(nextQueueIndex[vault], 1);

        // Update Standard Debt: SD = SD + lockedShares (netShares)
        standardDebt[vault] = MathLib.safeAdd(standardDebt[vault], netShares);

        emit RedemptionRequested(vault, owner, queueIndex, shares, receiver, referralCode);
    }

managerUserActions.cancelRedemption:
function cancelRedemption(
        address vault,
        uint256 queueIndex
    ) external override nonReentrant {

        // Validate and get redemption entry
        RedemptionQueueEntry memory entry = _validateAndGetRedemptionEntry(vault, queueIndex, true);

        // Spend allowance if caller is not the owner (before unlocking shares)
        if (entry.owner != msg.sender) {
            IVault(vault).spendAllowance(entry.owner, msg.sender, entry.lockedShares);
        }

        // Unlock shares for the owner (shares belong to owner, not necessarily msg.sender)
        IVault(vault).unlockShares(entry.owner, entry.lockedShares);

        // Update Standard Debt: SD = SD - lockedShares
        if (standardDebt[vault] < entry.lockedShares) {
            standardDebt[vault] = 0;
        } else {
            standardDebt[vault] = MathLib.safeSub(standardDebt[vault], entry.lockedShares);
        }

        // Remove from queue (delete entry, keep index unique)
        delete redemptionQueues[vault][queueIndex];

        emit RedemptionCancelled(vault, entry.owner, queueIndex, entry.lockedShares, entry.receiver);
    }

managerValidationAndSettlement._validateDeposit:
function _validateDeposit(
        address vault,
        address asset,
        uint256 amount,
        address receiver
    ) internal view {
        vault.requireNonZeroContract();
        asset.requireNonZero();
        receiver.requireNonZero();
        if (amount == 0) revert Errors.ZeroAmount();

        // Check vault is registered
        if (!contracts.registry.isVaultRegistered(vault))
            revert Errors.VaultNotRegistered(vault);

        // Check asset is whitelisted
        if (!isWhitelisted[vault][asset]) {
            revert Errors.AssetNotWhitelisted(vault, asset);
        }

        // Blacklist checks
        _notBlacklisted(msg.sender);
        _notBlacklisted(receiver);

        // Validate greenlist for sender and receiver
        _validateGreenlist(vault, msg.sender, receiver);

    }

managerValidationAndSettlement._validateRedeem:
function _validateRedeem(
        address vault,
        uint256 shares,
        address owner,
        address receiver
    ) internal view {
        vault.requireNonZeroContract();
        receiver.requireNonZero();
        if (shares == 0) revert Errors.ZeroAmount();

        // Blacklist checks: prevent blacklisted addresses from redeeming or receiving redemptions
        _notBlacklisted(owner);
        _notBlacklisted(receiver);
        _notBlacklisted(msg.sender);

        // Validate greenlist for owner and receiver
        _validateGreenlist(vault, owner, receiver);

        // Check redemptions are enabled
        if (!contracts.registry.isRedemptionEnabled(vault)) {
            revert Errors.RedemptionsDisabledForVault(vault);
        }

        // Check user has sufficient unlocked shares
        uint256 userBalance = IVault(vault).balanceOf(owner);
        if (userBalance < shares) {
            revert Errors.InsufficientShares(userBalance, shares);
        }
    }

managerValidationAndSettlement._validateGreenlist:
function _validateGreenlist(
        address vault,
        address address1,
        address address2
    ) internal view {
        // Check if greenlist feature is enabled for this vault
        bool greenlistEnabled = contracts.featureRegistry.isFeatureEnabled(
            vault,
            Constants.GREENLIST_FEATURE_ID
        );

        // This to avoid unnecessary gas costs if greenlist is not enabled
        if (greenlistEnabled) {
            // Get feature contract from feature registry
            address greenListContract = contracts.featureRegistry.getFeatureContract(
                Constants.GREENLIST_FEATURE_ID
            );

            if (
                !IGreenlistFeature(greenListContract).isUserGreenlisted(
                    vault,
                    address1
                )
            ) revert Errors.NotOnGreenlist(address1);
            if (
                !IGreenlistFeature(greenListContract).isUserGreenlisted(
                    vault,
                    address2
                )
            ) revert Errors.NotOnGreenlist(address2);
        }
    }

managerValidationAndSettlement._validateAndGetRedemptionEntry:
function _validateAndGetRedemptionEntry(
        address vault,
        uint256 queueIndex,
        bool isCancelRedemption
    ) internal view returns (RedemptionQueueEntry memory entry) {
        // Validate vault is non-zero and registered
        vault.requireNonZeroContract();
        if (!contracts.registry.isVaultRegistered(vault)) {
            revert Errors.VaultNotRegistered(vault);
        }

        // Check vault-level pause
        if (contracts.registry.vaultPaused(vault)) {
            revert Errors.VaultPaused(vault);
        }

        // Get and validate entry exists (owner is zero for never-assigned or deleted entries)
        entry = redemptionQueues[vault][queueIndex];
        if (entry.owner == address(0)) {
            revert Errors.InvalidQueueIndex(queueIndex);
        }

        // Blacklist check: prevent blacklisted addresses from processing redemptions
        _notBlacklisted(entry.owner);

        if (!isCancelRedemption) {
            _notBlacklisted(entry.receiver);
        }
    }

managerValidationAndSettlement._calculateDepositSharesFromAsset:
function _calculateDepositSharesFromAsset(
        address vault,
        address asset,
        uint256 amount,
        uint256 currentNav
    ) internal view returns (uint256 totalSharesToMint, uint256 depositValueInBase) {
        // Get and validate base asset
        address baseAsset = contracts.registry.baseAssets(vault);
        baseAsset.requireNonZero();

        uint256 depositPrice;
        bool priceValid;

        if (asset == baseAsset) {
            depositPrice = Constants.PRECISION;
            priceValid = true;
        }

        if (asset != baseAsset) {
            (depositPrice, priceValid) = contracts.priceOracle
                .getDepositPrice(asset, baseAsset);
            if (!priceValid || depositPrice == 0) {
                revert Errors.InvalidOraclePrice(asset, baseAsset, "INVALID_PRICE");
            }
        }

        // Calculate deposit value in base asset (18 decimals): m = q × P_asset,deposit
        // Work directly in 18 decimals to avoid unnecessary conversions
        uint8 assetDecimals = IERC20Metadata(asset).decimals(); // asset decimals

        // Scale amount to 18 decimals, then multiply by depositPrice (already 18 decimals)
        uint256 amountIn18Decimals = MathLib.scaleDecimals(amount, assetDecimals, 18);
        uint256 depositValueInBaseForShares = MathLib.mulDiv18(amountIn18Decimals, depositPrice);

        uint256 effectiveNav = _getMaxNavIfEnabled(vault, currentNav);

        // Calculate total shares to mint: ΔS = m / NAV (both in 18 decimals)
        totalSharesToMint = AccountingLib.calculateSharesToMint(depositValueInBaseForShares, effectiveNav);

        // Scale depositValueInBase to base asset decimals for limits validation
        depositValueInBase = MathLib.scaleDecimals(depositValueInBaseForShares, 18, IERC20Metadata(baseAsset).decimals());
    }

managerValidationAndSettlement._executeDeposit:
function _executeDeposit(
        address vault,
        address asset,
        uint256 amount,
        uint256 netShares,
        uint256 feeShares,
        address receiver,
        bytes32 referralCode
    ) internal {
        // Transfer assets to the vault deposit receiver
        _transferAssets(
            asset,
            msg.sender,
            contracts.registry.depositRecipients(vault),
            amount
        );

        // Mint fee shares directly to feeReceiver if applicable
        if (feeShares > 0) {
            address feeReceiver = contracts.registry.feeReceivers(vault);
            feeReceiver.requireNonZero();
            IVault(vault).mint(feeReceiver, feeShares);

            emit FeeTransferred(vault, feeReceiver, feeShares, FeeType.DepositFee, asset);
        }

        // Mint net shares to receiver (after fees)
        IVault(vault).mint(receiver, netShares);

        // Emit deposit event
        emit Deposit(vault, asset, msg.sender, receiver, amount, netShares, feeShares, referralCode);
    }

managerValidationAndSettlement._chargeRedemptionFeesAndLockShares:
function _chargeRedemptionFeesAndLockShares(
        address vault,
        address owner,
        uint256 shares
    ) internal returns (uint256 netShares) {
        // Get redemption configuration for fee calculation
        (address baseAsset, ) = _getRedemptionConfig(vault);
        address feeReceiver = contracts.registry.feeReceivers(vault);

        // Calculate redemption fees (fees are charged at request time)
        uint256 feeShares;

        if (owner == feeReceiver) {
            feeShares = 0;
            netShares = shares;
        } else {
            (netShares, feeShares) = _calculateFees(
                vault,
                baseAsset,
                shares,
                true // isRedemption = true
            );
        }

        // Spend allowance if caller is not the owner (before burning/locking shares)
        if (owner != msg.sender) {
            IVault(vault).spendAllowance(owner, msg.sender, shares);
        }

        // Mint fee shares directly to feeReceiver
        if (feeShares > 0) {
            IVault(vault).burn(owner, feeShares); // Burn fee shares from user's account
            feeReceiver.requireNonZero();
            IVault(vault).mint(feeReceiver, feeShares);
            emit FeeTransferred(vault, feeReceiver, feeShares, FeeType.RedemptionFee, baseAsset);
        }

        // Lock net shares (after fees are deducted)
        IVault(vault).lockShares(owner, netShares);
    }

managerValidationAndSettlement._calculateRedemptionAmounts:
function _calculateRedemptionAmounts(
        address vault,
        uint256 entryNavAtRequest,
        uint256 currentNav,
        uint256 netShares,
        address baseAsset
    ) internal view returns (uint256 effectiveNav, uint256 assetsToTransfer) {
        // Check if MIN_NAV feature is enabled
        bool minNavEnabled = contracts.featureRegistry.isFeatureEnabled(
            vault,
            Constants.MIN_NAV_FEATURE_ID
        );

        if(minNavEnabled) {
            effectiveNav = entryNavAtRequest < currentNav ? entryNavAtRequest : currentNav;
        } else {
            effectiveNav = currentNav;
        }

        // Calculate assets to transfer
        assetsToTransfer = _calculateRedemptionAssets(
            netShares,
            effectiveNav,
            baseAsset
        );
    }

managerValidationAndSettlement.processRedemption:
function processRedemption(
        address vault,
        uint256 queueIndex,
        uint256 gasFeeShares
    ) external override onlyOperator nonReentrant {
        // Validate and get redemption entry (includes vault validation, registration, entry existence, and blacklist checks)
        RedemptionQueueEntry memory entry = _validateAndGetRedemptionEntry(vault, queueIndex, false);

        // Extract entry fields to reduce stack depth
        address entryOwner = entry.owner;
        address entryReceiver = entry.receiver;
        uint256 entryLockedShares = entry.lockedShares;
        uint256 entryNavAtRequest = entry.navAtRequest;

        // Get current NAV (must be initialized)
        uint256 currentNav = _getAndValidateNav(vault);

        // Get redemption configuration
        (address baseAsset, address redemptionSource) = _getRedemptionConfig(vault);

        // Deduct gas fee shares from netShares (entryLockedShares is already netShares after fees)
        if (entryLockedShares < gasFeeShares) {
            revert Errors.InsufficientShares(entryLockedShares, gasFeeShares);
        }
        uint256 netShares = entryLockedShares - gasFeeShares;

        // Transfer gas fee shares to treasury
        if (gasFeeShares > 0) {
            treasury.requireNonZero();
            IVault(vault).mint(treasury, gasFeeShares);
        }

        // Calculate effective NAV and assets to transfer in helper function
        (uint256 effectiveNav, uint256 assetsToTransfer) = _calculateRedemptionAmounts(
            vault,
            entryNavAtRequest,
            currentNav,
            netShares,
            baseAsset
        );

        // Execute redemption processing (pass extracted values instead of full struct)
        _executeRedemptionProcessing(
            vault,
            entryOwner,
            entryReceiver,
            entryLockedShares,
            queueIndex,
            baseAsset,
            redemptionSource,
            assetsToTransfer
        );

        // Emit all events in main method
        emit RedemptionProcessed(
            vault,
            entryOwner,
            entryReceiver,
            queueIndex,
            assetsToTransfer,
            effectiveNav,
            entryLockedShares,
            gasFeeShares
        );
    }
